INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/amblypyge-noir#carte:amblypyge-de-brai', 1, NULL, NULL, 'Carapace huileuse', 'Les dégâts physiques infligés sur lui diminue de 5 en dégâts mais prend 5 dégâts de plus contre les dégâts de feu et de foudre.', 'monstres', 'Bestiaire 2.0 › ligne 763');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/amblypyge-noir#carte:amblypyge-de-brai', 2, NULL, NULL, 'Diagonale incohérente', 'Les diagonales comptent pour 1 case de déplacement.', 'monstres', 'Bestiaire 2.0 › ligne 763');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/amblypyge-noir#carte:amblypyge-de-brai', 3, NULL, NULL, 'Embuscade poisseuse', 'Si cette créature attaque alors qu''elle est dans l''obsurité, sur un marais, un terrain corrompu = +3 dégâts, +2% à la réussite critique', 'monstres', 'Bestiaire 2.0 › ligne 763');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/amblypyge-noir#carte:amblypyge-de-brai', 4, NULL, NULL, 'Pétrolier', 'Chaque attaque qui touche inflige 5 corruption.', 'monstres', 'Bestiaire 2.0 › ligne 763');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/amblypyge-noir#carte:amblypyge-de-brai', 5, NULL, NULL, 'Pincement entravante', 'Si la créature réussit son attaque avec son arme naturelle, elle empêche la cible d''utiliser des "réactions" pendant 1 tour.', 'monstres', 'Bestiaire 2.0 › ligne 763');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/amblypyge-noir#carte:amblypyge-de-brai', 6, NULL, NULL, 'Pétronage', 'La vitesse de nage dans le pétrole ou les marais est doublée, la vitesse augmente de +2 sous la météo “Pluie pétrole”.', 'monstres', 'Bestiaire 2.0 › ligne 763');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/amblypyge-noir#carte:amblypyge-de-corruption', 1, NULL, NULL, 'Grande créature', 'Cette créature est bien plus grande que les autres, ainsi les malus de visée des ennemis sont réduits de moitié. Chaque attaque physique prodiguée par la créature force un jet de stabilité/réflexe pour ne pas être repoussé de 1d4 cases en arrière et tomber au sol.', 'monstres', 'Bestiaire 2.0 › ligne 821');
