INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/blob-brun#carte:blob-de-la-terre', 4, NULL, NULL, 'Élément Terre', 'L’arme de cette créature possède 30% de chance d’obliger un jet de vigueur à l’adversaire pour ne pas qu’il prenne “pétrifié 1”. L’arme peut taper dans l’élément associé et ses sorts de terre infligent également un bonus de +3 aux dégâts.', 'monstres', 'Bestiaire 2.0 › ligne 2581');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/blob-brun#carte:blob-de-la-terre', 5, NULL, NULL, 'Égide', 'Permet de survivre à 1 santé contre une attaque qui est censée vous mettre dans le coma. Marche qu’une fois.', 'monstres', 'Bestiaire 2.0 › ligne 2581');
