INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/blob-vert#carte:blob-du-vent', 5, NULL, NULL, 'Plus rapide', 'Cette créature à un bonus de +3 à la vitesse et de +3 aux jets d''initiative.', 'monstres', 'Bestiaire 2.0 › ligne 5141');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/blob-vert#carte:blob-kiwi', 1, NULL, NULL, 'Inerte', 'Amplifie la Volonté à 10, ce qui permet d’être immunisé au jet de volonté (sauf contre les altérations d’état faible où un jet se fait avec un malus de 30).', 'monstres', 'Bestiaire 2.0 › ligne 5078');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/blob-vert#carte:blob-kiwi', 2, NULL, NULL, 'Gluant', 'Cette créature est faite dans une matière gélatineuse, ce qui lui permet d’être résistante face au dégâts de frappe. Sa structure lui inflige une faiblesse contre la paralysie.', 'monstres', 'Bestiaire 2.0 › ligne 5078');
