INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/casque-brise#carte:casque-brise', 1, NULL, NULL, 'Mourir peut attendre', 'Cette créature n’a que la moitié de sa santé qu’elle est censée avoir. Quand elle tombe en dessous de 0 santé, elle sombre dans une mort temporaire qui ne dure qu’un tour, à la fin de ce dernier, elle revient avec toute sa santé et barrière. La deuxième mort est fatale par contre.', 'monstres', 'Bestiaire 2.0 › ligne 5793');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/casque-brise#carte:casque-brise', 2, NULL, NULL, 'Vol', 'Cette créature est capable de voler et donc d’ignorer les terrains négatifs.', 'monstres', 'Bestiaire 2.0 › ligne 5793');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/casque-brise#carte:casque-brise', 3, NULL, NULL, 'Devoir de l’Éclaireur', 'Cette créature est perspicace, elle dispose d’une portée d’attaque qui va sur tout le terrain, ses attaques sont si rapides que la cible a un malus de 10% pour se défendre et une fois par tour elle peut ignorer une attaque d’opportunité.', 'monstres', 'Bestiaire 2.0 › ligne 5793');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/cerbere#carte:cerbere-adulte', 1, NULL, NULL, '3 têtes', 'Cette créature possède 3 initiatives et des dons différents selon la tête qui joue.', 'monstres', 'Bestiaire 2.0 › ligne 5930');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/cerbere#carte:cerbere-adulte', 2, '[Gauche]', NULL, 'Téméraire', 'Cette créature est toujours en offensive et n’est pas affectée par le malus pour toucher.', 'monstres', 'Bestiaire 2.0 › ligne 5930');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/cerbere#carte:cerbere-adulte', 3, '[Gauche]', NULL, 'Science du critique+', 'Cette créature a +3 à la réussite critique et à l’échec critique.', 'monstres', 'Bestiaire 2.0 › ligne 5930');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/cerbere#carte:cerbere-adulte', 4, '[Centre]', NULL, 'Défenseur', 'Cette créature est toujours en défensive.', 'monstres', 'Bestiaire 2.0 › ligne 5930');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/cerbere#carte:cerbere-adulte', 5, '[Centre]', NULL, 'Sujet épineux+', 'En posture de défense, cette créature inflige 10 dégâts lors d’une parade parfaite.', 'monstres', 'Bestiaire 2.0 › ligne 5930');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/cerbere#carte:cerbere-adulte', 6, '[Droite]', NULL, 'Concentré', 'Cette créature est toujours en focus.', 'monstres', 'Bestiaire 2.0 › ligne 5930');
