INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/cerbere#carte:cerbere-geant', 1, NULL, NULL, '3 têtes', 'Cette créature possède 3 initiatives et des dons différents selon la tête qui joue.', 'monstres', 'Bestiaire 2.0 › ligne 6002');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/cerbere#carte:cerbere-geant', 2, NULL, NULL, 'Grande créature', 'Cette créature est bien plus grande que les autres, ainsi les malus de visée des ennemis sont réduits de moitié. Chaque attaque physique prodiguée par la créature force un jet de stabilité pour ne pas être repoussé de 1d4 cases en arrière et tomber au sol.', 'monstres', 'Bestiaire 2.0 › ligne 6002');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/cerbere#carte:cerbere-geant', 3, '[Gauche]', NULL, 'Téméraire', 'Cette créature est toujours en offensive et n’est pas affectée par le malus pour toucher.', 'monstres', 'Bestiaire 2.0 › ligne 6002');
