INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/collecteur#carte:collecteur-puissant', 6, '[EP4]', 4, 'Grande créature', 'Cette créature est bien plus grande que les autres, ainsi les malus de visée des ennemis sont réduits de moitié. Chaque attaque physique prodiguée par la créature force un jet de stabilité pour ne pas être repoussé de 1d4 cases en arrière et tomber au sol.', 'monstres', 'Bestiaire 2.0 › ligne 6874');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/collecteur#carte:collecteur-puissant', 7, '[EP5]', 5, 'Statue', 'Si la créature n’a pas bougé durant ce tour, elle gagne +5AP mais perd 6 INI, et ceux jusqu''au début de son prochain tour.', 'monstres', 'Bestiaire 2.0 › ligne 6874');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/collecteur#carte:collecteur-puissant', 8, '[EP6]', 6, 'Racine', 'Si la créature n’a pas bougé durant ce tour, elle récupère 5% de sa santé max.', 'monstres', 'Bestiaire 2.0 › ligne 6874');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/collecteur#carte:collecteur-titan', 1, NULL, NULL, 'Non-Mort', 'Une créature non-mort est immunisée à la peur, à la couardise, à la fatigue, au poison, à la maladie. Les soins de lumière lui infligent des dégâts mais il a la possibilité de faire un jet de défense pour ne pas prendre les dégâts.', 'monstres', 'Bestiaire 2.0 › ligne 6983');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/collecteur#carte:collecteur-titan', 2, NULL, NULL, 'Squelettique', 'Rend cette créature immunisée aux attaques d’estoc.', 'monstres', 'Bestiaire 2.0 › ligne 6983');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/collecteur#carte:collecteur-titan', 3, NULL, NULL, 'Être de la Terre', 'Cette créature est capable de lancer des sorts de son niveau de puissance magique.', 'monstres', 'Bestiaire 2.0 › ligne 6983');
