INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/corbeau-agressif#carte:corbeau-agressif-noir', 3, NULL, NULL, 'Rage', 'Active un pouvoir de rage qui augmente de +3 les dégâts et de +2 les dégâts subis pendant 3 tours.', 'monstres', 'Bestiaire 2.0 › ligne 7073');
