INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/criquet-thaumivore#carte:criquet-thaumivore-geant', 1, NULL, NULL, 'Bond', 'Cette créature est capable de faire un bond équivalent à sa vitesse x2 en échange de 3IC.', 'monstres', 'Bestiaire 2.0 › ligne 7651');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/criquet-thaumivore#carte:criquet-thaumivore-geant', 2, NULL, NULL, 'Morsure aspirante bleue', 'La morsure de cette créature est capable d’aspirer le chakra de sa victime à hauteur de 30% par rapport aux dégâts infligés avec l’attaque.', 'monstres', 'Bestiaire 2.0 › ligne 7651');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/criquet-thaumivore#carte:criquet-thaumivore-geant', 3, NULL, NULL, 'Chargement bleu', 'Cette créature possède une réserve de chakra vide qui peut se remplir par un moyen x. Quand elle atteint certains seuil de réserve, elle débloque des passif qui se cumule entre eux :
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/criquet-thaumivore#carte:criquet-thaumivore-geant', 4, NULL, NULL, 'Charge chakratique', 'Quand la réserve de chakra atteint 100%, peut faire une charge sur une cible dont la portée correspond au sprint de la créature. Une fois cette attaque faite, la réserve de chakra retombe à 0.', 'monstres', 'Bestiaire 2.0 › ligne 7651');
