INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/cuirasse-abimee#carte:cuirasse-abime', 1, NULL, NULL, 'Mourir peut attendre', 'Cette créature n’a que la moitié de sa santé qu’elle est censée avoir. Quand elle tombe en dessous de 0 santé, elle sombre dans une mort temporaire qui ne dure qu’un tour, à la fin de ce dernier, elle revient avec toute sa santé et barrière. La deuxième mort est fatale par contre.', 'monstres', 'Bestiaire 2.0 › ligne 7721');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/cuirasse-abimee#carte:cuirasse-abime', 2, NULL, NULL, 'Vol', 'Cette créature est capable de voler et donc d’ignorer les terrains négatifs.', 'monstres', 'Bestiaire 2.0 › ligne 7721');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/cuirasse-abimee#carte:cuirasse-abime', 3, NULL, NULL, 'Devoir de l’Égide', 'Cette créature est robuste, il est capable de bloquer un adversaire dans sa zone d’influence mais également d’imposer un désavantage à ce même adversaire si il tente une attaque à distance ou un sort sur une autre cible que lui. Il peut bloquer 4 adversaires comme ça.', 'monstres', 'Bestiaire 2.0 › ligne 7721');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/darvask#carte:darvask-delta', 1, NULL, NULL, 'Grimpeur', 'Cette créature possède un moyen de grimper les murs ou toutes surfaces en hauteur. Elle n’a pas besoin de jet pour les traverser et elle ne consomme pas son tour.', 'monstres', 'Bestiaire 2.0 › ligne 7902');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/darvask#carte:darvask-delta', 2, NULL, NULL, 'Prise du jour', 'Lorsque cette créature utilise sa morsure, la cible est bloqué dans sa gueule et doit faire un jet d’athlétisme/équilibre au début de son tour de jeu pour en sortir :
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/darvask#carte:darvask-delta', 3, NULL, NULL, 'Écailles protecteurs', 'Les écailles de cette créature annulent 4 dégâts à chaque première attaque d’un tour.', 'monstres', 'Bestiaire 2.0 › ligne 7902');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/darvask#carte:darvask-delta', 4, NULL, NULL, 'Grande créature', 'Cette créature est bien plus grande que les autres, ainsi les malus de visée des ennemis sont réduits de moitié. Chaque attaque physique prodiguée par la créature force un jet de stabilité/réflexe pour ne pas être repoussé de 1d4 cases en arrière et tomber au sol.', 'monstres', 'Bestiaire 2.0 › ligne 7902');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/darvask#carte:darvask-delta', 5, NULL, NULL, 'Force démesurée', 'Cette créature peut dépasser la limite de Force de 1.', 'monstres', 'Bestiaire 2.0 › ligne 7902');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/darvask#carte:darvask-delta', 6, NULL, NULL, 'Folle de guerre', 'Cette créature doit avancer vers l’ennemi, elle ne peut pas attendre et est immunisée contre toutes formes de peur.', 'monstres', 'Bestiaire 2.0 › ligne 7902');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/darvask#carte:darvask-jeune', 1, NULL, NULL, 'Grimpeur', 'Cette créature possède un moyen de grimper les murs ou toutes surfaces en hauteur. Elle n’a pas besoin de jet pour les traverser et elle ne consomme pas son tour.', 'monstres', 'Bestiaire 2.0 › ligne 7792');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/darvask#carte:darvask-jeune', 2, NULL, NULL, 'Prise du jour', 'Lorsque cette créature utilise sa morsure, la cible est bloqué dans sa gueule et doit faire un jet d’athlétisme/équilibre au début de son tour de jeu pour en sortir :
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/darvask#carte:gros-darvask', 1, NULL, NULL, 'Grimpeur', 'Cette créature possède un moyen de grimper les murs ou toutes surfaces en hauteur. Elle n’a pas besoin de jet pour les traverser et elle ne consomme pas son tour.', 'monstres', 'Bestiaire 2.0 › ligne 7846');
