INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/darvask#carte:gros-darvask', 3, NULL, NULL, 'Écailles protecteurs', 'Les écailles de cette créature annulent 4 dégâts à chaque première attaque d’un tour.', 'monstres', 'Bestiaire 2.0 › ligne 7846');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/elementaire-de-la-foudre#carte:elementaire-de-la-foudre', 1, NULL, NULL, 'Inerte', 'Cette créature possède 10 de volonté et est donc immunisée contre les jets de Volonté (sauf les altérations d’état dont il est vulnérable, là il n’a que 50% de chance de les éviter).', 'monstres', 'Bestiaire 2.0 › ligne 8006');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/elementaire-de-la-foudre#carte:elementaire-de-la-foudre', 2, NULL, NULL, 'Grande créature', 'Cette créature est bien plus grande que les autres, ainsi les malus de visée des ennemis sont réduits de moitié. Chaque attaque physique prodiguée par la créature force un jet de stabilité/réflexe pour ne pas être repoussé de 1d4 cases en arrière et tomber au sol.', 'monstres', 'Bestiaire 2.0 › ligne 8006');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/elementaire-de-la-foudre#carte:elementaire-de-la-foudre', 3, NULL, NULL, 'Distributeur de dégâts', 'Les attaques physiques ou magiques de cette créature font 2 fois moins de dégâts mais elles sont capables de se distribuer aux ennemis qui sont trop proches de la cible initiale. Si un ennemi est à 3 cases ou moins de la cible initiale, il prend les dégâts et le distribuera si un autre ennemi est trop proche de lui, etc … Les ennemis ne peuvent pas prendre 2 fois l’attaque (impossible de faire une boucle infini).', 'monstres', 'Bestiaire 2.0 › ligne 8006');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/elementaire-de-la-foudre#carte:elementaire-de-la-foudre', 4, NULL, NULL, 'Lance foudre', 'A son tour, cette créature envoie une lance faite entièrement de foudre dans le ciel en cloche et va atterrir sur un ennemi aléatoire qui pourra tenter un jet de défense. C’est un IC.', 'monstres', 'Bestiaire 2.0 › ligne 8006');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/elementaire-de-la-foudre#carte:elementaire-de-la-foudre', 5, '[EP3]', 3, 'Être de la Foudre', 'Cette créature peut utiliser tous les sorts de la magie de la foudre de son niveau.', 'monstres', 'Bestiaire 2.0 › ligne 8006');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/elementaire-de-la-foudre#carte:elementaire-de-la-foudre', 6, '[EP5]', 5, 'Réponse mobile', 'A chaque attaque qu’il subit, il gagne +1 en vitesse pour 1 tour.', 'monstres', 'Bestiaire 2.0 › ligne 8006');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/elementaire-de-la-foudre#carte:elementaire-de-la-foudre', 7, '[EP7]', 7, 'Élan fulgurant', 'Quand la créature encaisse un coup, il peut se déplacer gratuitement devant un ennemi. Ne provoque pas d’attaque d’opportunité. (Réaction 1 fois/tour)', 'monstres', 'Bestiaire 2.0 › ligne 8006');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/elementaire-de-la-glace#carte:elementaire-de-glace', 1, NULL, NULL, 'Inerte', 'Cette créature possède 10 de volonté et est donc immunisée contre les jets de Volonté (sauf les altérations d’état dont il est vulnérable, là il n’a que 50% de chance de les éviter).', 'monstres', 'Bestiaire 2.0 › ligne 8185');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/elementaire-de-la-glace#carte:elementaire-de-glace', 2, NULL, NULL, 'Grande créature', 'Cette créature est bien plus grande que les autres, ainsi les malus de visée des ennemis sont réduits de moitié. Chaque attaque physique prodiguée par la créature force un jet de stabilité/réflexe pour ne pas être repoussé de 1d4 cases en arrière et tomber au sol.', 'monstres', 'Bestiaire 2.0 › ligne 8185');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/elementaire-de-la-glace#carte:elementaire-de-glace', 3, NULL, NULL, 'Reflet uni', 'Cette créature est comme divisée en deux parties, le total d’attributs est divisé en deux.', 'monstres', 'Bestiaire 2.0 › ligne 8185');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/elementaire-de-la-glace#carte:elementaire-de-glace', 4, NULL, NULL, 'Uni dans la mort', 'Cette créature est en symbiose complète avec une autre, mettre hors de combat l’une d’entre n’est pas suffisant, il est nécessaire que les deux créatures meurent quasiment au même moment. Si l’une d’entre elle tombe au combat, elle se relèvera après un tour avec 10% de sa santé.', 'monstres', 'Bestiaire 2.0 › ligne 8185');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/elementaire-de-la-glace#carte:elementaire-de-glace', 5, '(Neige) [EP3]', 3, 'Force démesurée', 'Cette créature peut dépasser la limite de Force de 1.', 'monstres', 'Bestiaire 2.0 › ligne 8185');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/elementaire-de-la-glace#carte:elementaire-de-glace', 6, '(Cristal) [EP3]', 3, 'Être de la Glace', 'Cette créature peut utiliser tous les sorts de la magie de la glace de son niveau.', 'monstres', 'Bestiaire 2.0 › ligne 8185');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/elementaire-de-la-glace#carte:elementaire-de-glace', 7, '(Neige) [EP5]', 5, 'Neige permanente', 'Invoque la météo “neige” en entrant sur le terrain et fait perdurer tant que personne ne la change.', 'monstres', 'Bestiaire 2.0 › ligne 8185');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/elementaire-de-la-glace#carte:elementaire-de-glace', 8, '(Cristal) [EP5]', 5, 'Perce-AM', 'Les sorts de cette créature ignorent 4AM.', 'monstres', 'Bestiaire 2.0 › ligne 8185');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/elementaire-de-la-glace#carte:elementaire-de-glace', 9, '(Neige/Cristal) [EP7]', 7, 'Dans mon élément', 'Si cette créature se retrouve dans un environnement lié à sa magie (météo ou terrain), inflige un bonus de +7 à tous les dégâts, +3AM et AP, +5% à tous les jets de dés et +1% à la RC.', 'monstres', 'Bestiaire 2.0 › ligne 8185');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/elementaire-de-la-lumiere#carte:elementaire-de-la-lumiere', 1, NULL, NULL, 'Inerte', 'Cette créature possède 10 de volonté et est donc immunisée contre les jets de Volonté (sauf les altérations d’état dont il est vulnérable, là il n’a que 50% de chance de les éviter).', 'monstres', 'Bestiaire 2.0 › ligne 8326');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/elementaire-de-la-lumiere#carte:elementaire-de-la-lumiere', 2, NULL, NULL, 'Grande créature', 'Cette créature est bien plus grande que les autres, ainsi les malus de visée des ennemis sont réduits de moitié. Chaque attaque physique prodiguée par la créature force un jet de stabilité/réflexe pour ne pas être repoussé de 1d4 cases en arrière et tomber au sol.', 'monstres', 'Bestiaire 2.0 › ligne 8326');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/elementaire-de-la-lumiere#carte:elementaire-de-la-lumiere', 3, NULL, NULL, 'Champ protecteur', 'A chaque coup que prend la créature, un champ de force va être invoqué et peut encaisser la même quantité de dégâts que le coup précédant. Pour qu’un champ de force apparaisse, il faut attendre que la créature n’est plus rien et qu’elle prenne un coup.', 'monstres', 'Bestiaire 2.0 › ligne 8326');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/elementaire-de-la-lumiere#carte:elementaire-de-la-lumiere', 4, NULL, NULL, 'Rayon d’Aurora', 'Invoque “Grand Soleil” dès le début du combat.', 'monstres', 'Bestiaire 2.0 › ligne 8326');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/elementaire-de-la-lumiere#carte:elementaire-de-la-lumiere', 5, '[EP3]', 3, 'Être de la Lumière', 'Cette créature peut utiliser tous les sorts de la magie de la lumière de son niveau.', 'monstres', 'Bestiaire 2.0 › ligne 8326');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/elementaire-de-la-lumiere#carte:elementaire-de-la-lumiere', 6, '[EP5]', 5, 'Répression solaire', 'La météo “grand soleil” ne peut être annulée ou remplacée tant qu’elle est là.', 'monstres', 'Bestiaire 2.0 › ligne 8326');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/elementaire-de-la-lumiere#carte:elementaire-de-la-lumiere', 7, '[EP7]', 7, 'Puissance solaire', 'Tant qu’une météo qui avantage la lumière est présente = +12 dégâts.', 'monstres', 'Bestiaire 2.0 › ligne 8326');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/elementaire-de-la-necromancie#carte:elementaire-de-la-necromancie', 1, NULL, NULL, 'Inerte', 'Cette créature possède 10 de volonté et est donc immunisée contre les jets de Volonté (sauf les altérations d’état dont il est vulnérable, là il n’a que 50% de chance de les éviter).', 'monstres', 'Bestiaire 2.0 › ligne 8448');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/elementaire-de-la-necromancie#carte:elementaire-de-la-necromancie', 2, NULL, NULL, 'Serviteur toxique', 'Cette créature n’attaque pas directement, elle se cache derrière une cage d’os indestructible et lance ses invocations contre ses ennemis, elle peut en invoquer 4 à la fois, sans jet, a accès à toutes les invocations de la nécromancie et les remplace le tour après leur mort. Une fois qu’une invocation est tuée, la santé qu’elle possédait sera infligée contre la santé du boss (pas sa barrière). Il peut lancer les invocations selon son niveau de puissance magique.', 'monstres', 'Bestiaire 2.0 › ligne 8448');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/elementaire-de-la-necromancie#carte:elementaire-de-la-necromancie', 3, NULL, NULL, 'Demi-santé', 'Cette créature a deux fois moins de santé.', 'monstres', 'Bestiaire 2.0 › ligne 8448');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/elementaire-de-la-necromancie#carte:elementaire-de-la-necromancie', 4, '[EP3]', 3, 'Être de la Nécromancie', 'Cette créature peut utiliser tous les sorts de la magie de la nécromancie de son niveau.', 'monstres', 'Bestiaire 2.0 › ligne 8448');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/elementaire-de-la-necromancie#carte:elementaire-de-la-necromancie', 5, '[EP5]', 5, 'Aura de grand chef', 'Donne un bonus de +5 aux dégâts de ses alliés tant qu’il est encore debout.', 'monstres', 'Bestiaire 2.0 › ligne 8448');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/elementaire-de-la-necromancie#carte:elementaire-de-la-necromancie', 6, '[EP7]', 7, 'Général non-mort', 'Si d’autres non-mort sont présents sur le terrain et sont ses alliés : +6 dégâts et +1 Vitesse tant que la créature est en vie.', 'monstres', 'Bestiaire 2.0 › ligne 8448');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/elementaire-de-la-terre#carte:elementaire-de-la-terre', 1, NULL, NULL, 'Inerte', 'Cette créature possède 10 de volonté et est donc immunisée contre les jets de Volonté (sauf les altérations d’état dont il est vulnérable, là il n’a que 50% de chance de les éviter).', 'monstres', 'Bestiaire 2.0 › ligne 8580');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/elementaire-de-la-terre#carte:elementaire-de-la-terre', 2, NULL, NULL, 'Grande créature', 'Cette créature est bien plus grande que les autres, ainsi les malus de visée des ennemis sont réduits de moitié. Chaque attaque physique prodiguée par la créature force un jet de stabilité/réflexe pour ne pas être repoussé de 1d4 cases en arrière et tomber au sol.', 'monstres', 'Bestiaire 2.0 › ligne 8580');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/elementaire-de-la-terre#carte:elementaire-de-la-terre', 3, NULL, NULL, 'Terraformation', 'A chaque fois que la créature perd 30% de sa santé max, il se déplace gratuitement sur le terrain et ce dernier est totalement changé avec des murs et des obstacles nouveaux.', 'monstres', 'Bestiaire 2.0 › ligne 8580');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/elementaire-de-la-terre#carte:elementaire-de-la-terre', 4, NULL, NULL, 'Au-delà de la portée', 'Cette créature peut utiliser les obstacles sur le terrain comme extension de portée et frapper les ennemis qui sont à deux cases d’eux. Ses armes font deux fois moins de dégâts quand il use de cette méthode pour atteindre un ennemi (sauf quand il lui reste moins de 40% de sa santé).', 'monstres', 'Bestiaire 2.0 › ligne 8580');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/elementaire-de-la-terre#carte:elementaire-de-la-terre', 5, '[EP3]', 3, 'Être de la Terre', 'Cette créature peut utiliser tous les sorts de la magie de la terre de son niveau.', 'monstres', 'Bestiaire 2.0 › ligne 8580');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/elementaire-de-la-terre#carte:elementaire-de-la-terre', 6, '[EP5]', 5, 'Multi-racines', 'Cette créature est capable avec l’une de ses *armes de frapper l’intégralité des ennemis sur le terrain et sans limite de portée.', 'monstres', 'Bestiaire 2.0 › ligne 8580');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/elementaire-de-la-terre#carte:elementaire-de-la-terre', 7, '[EP7]', 7, 'Liane ralentisseur', 'Les sorts ou armes en lien avec les plantes qui touchent une cible lui retirent également 1 de vitesse pour son prochain tour.', 'monstres', 'Bestiaire 2.0 › ligne 8580');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/elementaire-de-larcane#carte:elementaire-de-larcane', 1, NULL, NULL, 'Inerte', 'Cette créature possède 10 de volonté et est donc immunisée contre les jets de Volonté (sauf les altérations d’état dont il est vulnérable, là il n’a que 50% de chance de les éviter).', 'monstres', 'Bestiaire 2.0 › ligne 8707');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/elementaire-de-larcane#carte:elementaire-de-larcane', 2, NULL, NULL, 'Grande créature', 'Cette créature est bien plus grande que les autres, ainsi les malus de visée des ennemis sont réduits de moitié. Chaque attaque physique prodiguée par la créature force un jet de stabilité/réflexe pour ne pas être repoussé de 1d4 cases en arrière et tomber au sol.', 'monstres', 'Bestiaire 2.0 › ligne 8707');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/elementaire-de-larcane#carte:elementaire-de-larcane', 3, NULL, NULL, 'Vol', 'Cette créature est capable de voler et donc d’ignorer les terrains négatifs.', 'monstres', 'Bestiaire 2.0 › ligne 8707');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/elementaire-de-larcane#carte:elementaire-de-larcane', 4, NULL, NULL, 'Blessure chakratique', 'Cette créature exploite le chakra de ses adversaire à son avantage, elle obtient un bonus de 1 dégât à ses attaques par 5 chakra courant dans la réserve de sa cible. Quand ses ennemis utilisent du chakra, si leur score de réussite est au dessus de 75, ils perdent le quart du coût en chakra du sort en santé (minimum 1 santé).', 'monstres', 'Bestiaire 2.0 › ligne 8707');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/elementaire-de-larcane#carte:elementaire-de-larcane', 5, '[EP3]', 3, 'Être de l‘Arcane', 'Cette créature peut utiliser tous les sorts de la magie de l’arcane de son niveau.', 'monstres', 'Bestiaire 2.0 › ligne 8707');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/elementaire-de-larcane#carte:elementaire-de-larcane', 6, '[EP5]', 5, 'Brûlure chakratique', 'Tant qu’elle est sur le terrain, cette créature augmente les coûts en chakra de 50% pour ses ennemis.', 'monstres', 'Bestiaire 2.0 › ligne 8707');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/elementaire-de-larcane#carte:elementaire-de-larcane', 7, '[EP7]', 7, 'Cadeau chakratique', 'Cette créature peut donner une partie de son chakra à une cible. (3 fois/combat)', 'monstres', 'Bestiaire 2.0 › ligne 8707');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/elementaire-de-leau#carte:elementaire-de-leau', 1, NULL, NULL, 'Inerte', 'Cette créature possède 10 de volonté et est donc immunisée contre les jets de Volonté (sauf les altérations d’état dont il est vulnérable, là il n’a que 50% de chance de les éviter).', 'monstres', 'Bestiaire 2.0 › ligne 8843');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/elementaire-de-leau#carte:elementaire-de-leau', 2, NULL, NULL, 'Grande créature', 'Cette créature est bien plus grande que les autres, ainsi les malus de visée des ennemis sont réduits de moitié. Chaque attaque physique prodiguée par la créature force un jet de stabilité/réflexe pour ne pas être repoussé de 1d4 cases en arrière et tomber au sol.', 'monstres', 'Bestiaire 2.0 › ligne 8843');
