INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/elementaire-de-leau#carte:elementaire-de-leau', 4, NULL, NULL, 'État altéré', 'Les armes de cette créature ont 25% de chance de forcer un jet pour ne pas prendre une altération d’état mais ce dernier change selon l’état de la créature :
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/elementaire-de-leau#carte:elementaire-de-leau', 5, '[EP3]', 3, 'Être de l’Eau', 'Cette créature peut utiliser tous les sorts de la magie de l’eau de son niveau.', 'monstres', 'Bestiaire 2.0 › ligne 8843');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/elementaire-de-leau#carte:elementaire-de-leau', 6, '[EP5]', 5, 'États parfaits', 'La résistance obtenue par l’état solide et gazeux deviennent des immunités.', 'monstres', 'Bestiaire 2.0 › ligne 8843');
