INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/elementaire-de-lespace-temps#carte:elementaire-de-lespace-temps', 1, NULL, NULL, 'Inerte', 'Cette créature possède 10 de volonté et est donc immunisée contre les jets de Volonté (sauf les altérations d’état dont il est vulnérable, là il n’a que 50% de chance de les éviter).', 'monstres', 'Bestiaire 2.0 › ligne 8984');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/elementaire-de-lespace-temps#carte:elementaire-de-lespace-temps', 2, NULL, NULL, 'Grande créature', 'Cette créature est bien plus grande que les autres, ainsi les malus de visée des ennemis sont réduits de moitié. Chaque attaque physique prodiguée par la créature force un jet de stabilité/réflexe pour ne pas être repoussé de 1d4 cases en arrière et tomber au sol.', 'monstres', 'Bestiaire 2.0 › ligne 8984');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/elementaire-de-lespace-temps#carte:elementaire-de-lespace-temps', 3, NULL, NULL, 'Rythme étrange', 'Les tours pairs elle est vulnérable au dégâts physiques et insensible aux dégâts magique et inversement les tour impairs', 'monstres', 'Bestiaire 2.0 › ligne 8984');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/elementaire-de-lespace-temps#carte:elementaire-de-lespace-temps', 4, NULL, NULL, '25h', 'Cette créature est capable d’utiliser un sortilège de l’Espace/Temps qui est capable de placement, le sort ne fera rien d’autre que l’effet de placement. Cet IC peut se faire avant, après ou pendant le tour réel de la créature (1 fois par tour)', 'monstres', 'Bestiaire 2.0 › ligne 8984');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/elementaire-de-lespace-temps#carte:elementaire-de-lespace-temps', 5, '[EP3]', 3, 'Être de l’Espace/Temps', 'Cette créature peut utiliser tous les sorts de la magie de l’espace/temps de son niveau.', 'monstres', 'Bestiaire 2.0 › ligne 8984');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/elementaire-de-lespace-temps#carte:elementaire-de-lespace-temps', 6, '[EP5]', 5, 'Annule horloge', 'Si un adversaire fait un jet de dé et que le nombre 6, 12 ou 24 est le résultat, le dé est totalement annulé (que ce soit action ou dégâts). Si c''est l''initiative, elle tombe à 0.', 'monstres', 'Bestiaire 2.0 › ligne 8984');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/elementaire-de-lespace-temps#carte:elementaire-de-lespace-temps', 7, '[EP7]', 7, 'Super horloge', 'Si cette créature fait un 6, 12 ou 24 = c’est une réussite critique.', 'monstres', 'Bestiaire 2.0 › ligne 8984');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/elementaire-de-lombre#carte:elementaire-de-lombre', 1, NULL, NULL, 'Inerte', 'Cette créature possède 10 de volonté et est donc immunisée contre les jets de Volonté (sauf les altérations d’état dont il est vulnérable, là il n’a que 50% de chance de les éviter).', 'monstres', 'Bestiaire 2.0 › ligne 9117');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/elementaire-de-lombre#carte:elementaire-de-lombre', 2, NULL, NULL, 'Grande créature', 'Cette créature est bien plus grande que les autres, ainsi les malus de visée des ennemis sont réduits de moitié. Chaque attaque physique prodiguée par la créature force un jet de stabilité/réflexe pour ne pas être repoussé de 1d4 cases en arrière et tomber au sol.', 'monstres', 'Bestiaire 2.0 › ligne 9117');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/elementaire-de-lombre#carte:elementaire-de-lombre', 3, NULL, NULL, 'Copie brumeuse', 'Cette créature imite ses adversaires en créer des copies d’ombre de ces derniers, la puissance de ces copies dépend entièrement des originaux. L’une des copies est tangible et est le seul moyen d’infliger des dégâts à l’élémentaire. Chaque attaque qui est tenté contre lui (réussi ou raté), il se déplace de copie, un jet d’observation/distinction peut être tenté au début du tour pour repérer celui qui est tangible.', 'monstres', 'Bestiaire 2.0 › ligne 9117');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/elementaire-de-lombre#carte:elementaire-de-lombre', 4, NULL, NULL, 'Sournois', 'Quand l’adversaire n’est pas attentif à l’attaquant, permet d’infliger un bonus de 2d4 dégâts en plus des dégâts de l’arme.', 'monstres', 'Bestiaire 2.0 › ligne 9117');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/elementaire-de-lombre#carte:elementaire-de-lombre', 5, NULL, NULL, 'Demi-santé', 'Cette créature a deux fois moins de santé.', 'monstres', 'Bestiaire 2.0 › ligne 9117');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/elementaire-de-lombre#carte:elementaire-de-lombre', 6, '[EP3]', 3, 'Être de l’Ombre', 'Cette créature peut utiliser tous les sorts de la magie de l’ombre de son niveau.', 'monstres', 'Bestiaire 2.0 › ligne 9117');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/elementaire-de-lombre#carte:elementaire-de-lombre', 7, '[EP5]', 5, 'Attaque maudite', 'L''attaque de cette créature à l''effet du sort de l''ombre "malédiction" et l''applique automatiquement pendant 1 tour.', 'monstres', 'Bestiaire 2.0 › ligne 9117');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/elementaire-de-lombre#carte:elementaire-de-lombre', 8, '[EP7]', 7, 'Brouillard de l’assassin', 'Pose automatiquement la météo “brouillard obscur” et le fait perdurer tant qu’il n’est pas changé. Les attaques discrètes sont garanties à chacune de ses attaques tant que la météo est présente.', 'monstres', 'Bestiaire 2.0 › ligne 9117');
