INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/elementaire-du-feu#carte:elementaire-du-feu', 3, NULL, NULL, 'Brasier unifié', 'Quand la créature perd 25% de santé, elle va se diviser en deux, ces deux nouveaux être se partagent la santé courante mais conserve la puissance de base. Ce processus peut se faire 3 fois maximum. Une fois que la première division à eu lieu, les créatures nouvelles n''ont qu’une seule initiative.', 'monstres', 'Bestiaire 2.0 › ligne 9253');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/elementaire-du-feu#carte:elementaire-du-feu', 4, '[EP3]', 3, 'Être du Feu', 'Cette créature peut utiliser tous les sorts de la magie du feu de son niveau.', 'monstres', 'Bestiaire 2.0 › ligne 9253');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/elementaire-du-feu#carte:elementaire-du-feu', 5, '[EP5]', 5, 'Petit et rapide', 'La division 2 et 3 ont un bonus de +4 à l’initiative et +1 à la vitesse.', 'monstres', 'Bestiaire 2.0 › ligne 9253');
