INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/elementaire-du-vent#carte:elementaire-du-vent', 3, NULL, NULL, 'Vol', 'Cette créature est capable de voler et donc d’ignorer les terrains négatifs.', 'monstres', 'Bestiaire 2.0 › ligne 9537');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/elementaire-du-vent#carte:elementaire-du-vent', 4, NULL, NULL, 'Corps de cyclone', 'Cette créature se place au centre (5x5) de la battlemap et force ses ennemis à aller dans les coins. Les ennemis doivent se déplacer dans le cyclone au centre pour lui faire des dégâts. Il est nécessaire de réussir des jet de stabilité/réflexe pour pouvoir avancer dans la tornade, un échec divise par 2 la vitesse pour 1 tour. Il est impossible de sprinter dans la tornade. Si jamais un ennemi retombe dans la tornade, il est repoussé de 1d4 cases en arrière. Au sein du cyclone, les projectiles et attaques magiques ne fonctionnent pas et ne peuvent pas atteindre le centre.', 'monstres', 'Bestiaire 2.0 › ligne 9537');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/elementaire-du-vent#carte:elementaire-du-vent', 5, NULL, NULL, 'Allonge inattendue', 'Augmente la portée des sorts d''attaque de +3.', 'monstres', 'Bestiaire 2.0 › ligne 9537');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/elementaire-du-vent#carte:elementaire-du-vent', 6, '[EP3]', 3, 'Être du Vent', 'Cette créature peut utiliser tous les sorts de la magie du vent de son niveau.', 'monstres', 'Bestiaire 2.0 › ligne 9537');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/elementaire-du-vent#carte:elementaire-du-vent', 7, '[EP5]', 5, 'Prédateur aérien', 'Bonus de +6 dégâts contre les ennemis qui souffrent d''un malus à la vitesse ou à l''initiative (hors agilité à 1).', 'monstres', 'Bestiaire 2.0 › ligne 9537');
