INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/elementaire-du-vide#carte:elementaire-du-vide', 5, '[EP3]', 3, 'Être du vide', 'Cette créature peut utiliser tous les sorts de la magie du vide de son niveau.', 'monstres', 'Bestiaire 2.0 › ligne 9671');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/elementaire-du-vide#carte:elementaire-du-vide', 6, '[EP5]', 5, 'Totem du néant', 'Les ennemis à 3 cases autour de la créature ont un malus de 10% à tous les jets qui implique la volonté.', 'monstres', 'Bestiaire 2.0 › ligne 9671');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/elementaire-du-vide#carte:elementaire-du-vide', 7, '[EP7]', 7, 'Attaque dissipante', 'Tous les 2 tours, l’attaque de cette créature inflige l’effet du sort “dissipation” de la magie du vide.', 'monstres', 'Bestiaire 2.0 › ligne 9671');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/embrase#carte:embrase', 1, NULL, NULL, 'Non-Mort', 'Une créature non-mort est immunisée à la peur, à la couardise, à la fatigue, au poison, à la maladie. Les soins de lumière lui infligent des dégâts mais il a la possibilité de faire un jet de défense pour ne pas prendre les dégâts.', 'monstres', 'Bestiaire 2.0 › ligne 9799');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/embrase#carte:embrase', 2, NULL, NULL, 'Squelettique', 'Rend cette créature immunisé aux attaques d’estoc', 'monstres', 'Bestiaire 2.0 › ligne 9799');
