INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/embrase#carte:embrase-cramoisie', 7, NULL, NULL, 'Déflagration', 'Sacrifie la valeur de AP et AM pour les ajoutés comme modificateur au dégâts pendant 3 tours.', 'monstres', 'Bestiaire 2.0 › ligne 9916');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/epee-rouillee#carte:epee-rouillee', 1, NULL, NULL, 'Mourir peut attendre', 'Cette créature n’a que la moitié de sa santé qu’elle est censée avoir. Quand elle tombe en dessous de 0 santé, elle sombre dans une mort temporaire qui ne dure qu’un tour, à la fin de ce dernier, elle revient avec toute sa santé et barrière. La deuxième mort est fatale par contre.', 'monstres', 'Bestiaire 2.0 › ligne 9990');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/epee-rouillee#carte:epee-rouillee', 2, NULL, NULL, 'Vol', 'Cette créature est capable de voler et donc d’ignorer les terrains négatifs.', 'monstres', 'Bestiaire 2.0 › ligne 9990');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/epee-rouillee#carte:epee-rouillee', 3, NULL, NULL, 'Devoir de l’Attaquant', 'Cette créature est puissante, il est capable d’utiliser son arme en mordhau en plus d’avoir un bonus de +5* aux dégâts. Son style de combat est si particulier qu’il empêche toute contre-attaque et son lien profond avec son arme fait qu’il ne peut pas être désarmé.', 'monstres', 'Bestiaire 2.0 › ligne 9990');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/fourbraise#carte:fourbraise-chevaleresse', 1, NULL, NULL, 'Souffle élémentaire', 'Cette créature est capable de cracher un souffle lié à son élément. Ce souffle est capable d''infliger l''altération d''état lié à l''élément à hauteur de 35% de chance de l''infliger. (les joueurs doivent faire les jets en conséquences pour ne pas prendre l''altération d''état)', 'monstres', 'Bestiaire 2.0 › ligne 10151');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/fourbraise#carte:fourbraise-chevaleresse', 2, NULL, NULL, 'Super santé', 'Cette créature a le double de santé.', 'monstres', 'Bestiaire 2.0 › ligne 10151');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/fourbraise#carte:fourbraise-ouvriere', 1, NULL, NULL, 'Souffle élémentaire', 'Cette créature est capable de cracher un souffle lié à son élément. Ce souffle est capable d''infliger l''altération d''état lié à l''élément à hauteur de 35% de chance de l''infliger. (les joueurs doivent faire les jets en conséquences pour ne pas prendre l''altération d''état)', 'monstres', 'Bestiaire 2.0 › ligne 10053');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/fourbraise#carte:fourbraise-ouvriere', 2, NULL, NULL, 'Esprit de meute', 'Cette créature gagne un bonus de +5% à tous ses jets par alliés dans une zone de 2 cases autour de lui.', 'monstres', 'Bestiaire 2.0 › ligne 10053');
