INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/gants-usages#carte:gants-usages', 3, NULL, NULL, 'Devoir du Magicien', 'Cette créature versatile, anciennement du Potentiel Illimité, est capable d’utiliser tous les sorts d’attaques et d’entraves de niveau 1 en plus d’avoir un bonus de 5 aux dégâts des sorts.', 'monstres', 'Bestiaire 2.0 › ligne 10532');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/gardien-du-passe#carte:gardien-du-passe', 1, NULL, NULL, 'Vol', 'Cette créature est capable de voler et donc d’ignorer les terrains négatifs.', 'monstres', 'Bestiaire 2.0 › ligne 10600');
