INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/garrestre#carte:garrestre-puissant', 1, NULL, NULL, 'Lien forestier', 'Tant qu’il est dans la forêt, il bénéficie d’une bonus à la réussite de 5% et d’un bonus aux dégâts de 2. Sortir de la forêt fait qu’il peut en mourir.', 'monstres', 'Bestiaire 2.0 › ligne 10751');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/garrestre#carte:garrestre-puissant', 2, NULL, NULL, 'Racine', 'Tant qu''il est sur de la terre, cette créature récupère 3 santé au début de son tour.', 'monstres', 'Bestiaire 2.0 › ligne 10751');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/garrestre#carte:garrestre-puissant', 3, NULL, NULL, 'Folle de guerre', 'Cette créature doit avancer vers l’ennemi, elle ne peut pas attendre et est immunisée contre toutes formes de peur.', 'monstres', 'Bestiaire 2.0 › ligne 10751');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/garrestre#carte:garrestre-puissant', 4, NULL, NULL, 'Grande créature', 'Cette créature est bien plus grande que les autres, ainsi les malus de visée des ennemis sont réduits de moitié. Chaque attaque physique prodiguée par la créature force un jet de stabilité/réflexe pour ne pas être repoussé de 1d4 cases en arrière et tomber au sol.', 'monstres', 'Bestiaire 2.0 › ligne 10751');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/garrestre#carte:garrestre-puissant', 5, NULL, NULL, 'Fracas', 'Une arme* de cette créature est capable de se détruire et toucher ceux qui sont à 2 cases autour de la zone d’impact.', 'monstres', 'Bestiaire 2.0 › ligne 10751');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/garrestre#carte:garrestre-puissant', 6, NULL, NULL, 'Force démesurée', 'Cette créature peut dépasser la limite de Force de 1.', 'monstres', 'Bestiaire 2.0 › ligne 10751');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/garrestre#carte:garrestre-sage', 1, NULL, NULL, 'Lien forestier', 'Tant qu’il est dans la forêt, il bénéficie d’une bonus à la réussite de 5% et d’un bonus aux dégâts de 2. Sortir de la forêt fait qu’il peut en mourir.', 'monstres', 'Bestiaire 2.0 › ligne 10803');
