INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/garrestre#carte:garrestre-sage', 5, NULL, NULL, 'Élément Terre', 'L’arme de cette créature possède 30% de chance d’obliger un jet de fermeté à l’adversaire pour ne pas qu’il prenne “pétrifié 1”. L’arme peut taper dans l’élément associé et ses sorts de terre infligent également un bonus de +3 aux dégâts.', 'monstres', 'Bestiaire 2.0 › ligne 10803');
