INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-pain-dor#carte:golem-de-pain-dor', 1, NULL, NULL, 'Golem', 'Cette créature ne peut récupérer de la santé que via des réparations ou des sorts adaptés.', 'monstres', 'Bestiaire 2.0 › ligne 16191');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-pain-dor#carte:golem-de-pain-dor', 2, NULL, NULL, 'Inerte', 'Cette créature possède 10 de volonté et est donc immunisée contre les jets de Volonté (sauf les altérations d’état dont il est vulnérable, là il n’a que 50% de chance de les éviter).', 'monstres', 'Bestiaire 2.0 › ligne 16191');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-pain-dor#carte:golem-de-pain-dor', 3, NULL, NULL, 'Inaltérable', 'Résiste aux sorts ou actions qui pourrait lui détruire sa structure.', 'monstres', 'Bestiaire 2.0 › ligne 16191');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-pain-dor#carte:golem-de-pain-dor', 4, NULL, NULL, 'Grande créature', 'Cette créature est bien plus grande que les autres, ainsi les malus de visée des ennemis sont réduits de moitié. Chaque attaque physique prodiguée par la créature force un jet de stabilité/réflexe pour ne pas être repoussé de 1d4 cases en arrière et tomber au sol.', 'monstres', 'Bestiaire 2.0 › ligne 16191');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-pain-dor#carte:golem-de-pain-dor', 5, NULL, NULL, 'Régénération', 'Cette créature récupère 10 santé au début de chacun de ses tours.', 'monstres', 'Bestiaire 2.0 › ligne 16191');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-pain-dor#carte:golem-de-pain-dor', 6, NULL, NULL, 'Lanceur de poids', 'Cette créature peut ajouter son score de Force à sa portée maximale de son arme à distance.', 'monstres', 'Bestiaire 2.0 › ligne 16191');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-pain-dor#carte:golem-de-pain-dor', 7, NULL, NULL, 'Cuisson absolue', 'La peau de cette créature réagit aux éléments qu’on lui inflige, changeant sa peau et lui donne des propriétés. Cet état dure 3 tours tant qu’un autre élément n’est pas utilisé pour le remplacer, au bout de 3 tours, il redevient neutre. Utiliser un élément contraire à celui actif enclenche une “contre-cuisson”, l’effet de contre cuisson peut être esquiver ou parer s’il inflige des dégâts (sauf contre indication).
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-petrole#carte:golem-de-petrole-i', 1, NULL, NULL, 'Golem', 'Cette créature ne peut récupérer de la santé que via des réparations ou des sorts adaptés.', 'monstres', 'Bestiaire 2.0 › ligne 16569');
