INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-petrole#carte:golem-de-petrole-i', 4, NULL, NULL, 'Gluant', 'Cette créature est faite dans une matière gélatineuse, ce qui lui permet d’être résistante face au dégâts de frappe. Sa structure lui inflige une faiblesse contre la paralysie.', 'monstres', 'Bestiaire 2.0 › ligne 16569');
