INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-rouage#carte:golem-de-rouage-iii', 4, NULL, NULL, '25h', 'Cette créature est capable d’utiliser un sortilège de l’Espace/Temps qui est capable de placement, le sort ne fera rien d’autre que l’effet de placement. Cet IC peut se faire avant, après ou pendant le tour réel de la créature (1 fois par tour)', 'monstres', 'Bestiaire 2.0 › ligne 17026');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-rouage#carte:golem-de-rouage-iii', 5, NULL, NULL, 'Couple extrémité', 'Les tours impairs = Commence en premier le tour. Les tours pairs = Commence en dernier le tour', 'monstres', 'Bestiaire 2.0 › ligne 17026');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-rouage#carte:golem-de-rouage-iii', 6, NULL, NULL, 'Diagonale incohérente', 'Les diagonales comptent pour 1 case de déplacement au lieu de 2.', 'monstres', 'Bestiaire 2.0 › ligne 17026');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-rouage#carte:golem-de-rouage-iii', 7, NULL, NULL, 'Sulfateuse', 'Les arbalètes n’ont plus de recharge longue.', 'monstres', 'Bestiaire 2.0 › ligne 17026');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-rouage#carte:golem-de-rouage-iii', 8, NULL, NULL, 'Super 12', 'Si cette créature fait un 12, c’est une réussite critique.', 'monstres', 'Bestiaire 2.0 › ligne 17026');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-rouage#carte:golem-de-rouage-iii', 9, NULL, NULL, 'Annule 12', 'Si un adversaire fait un jet de dé et que le nombre 12 est présent dans le résultat, le dé est totalement annulé (que ce soit action ou dégâts). Si c''est l''initiative, elle tombe à 0.', 'monstres', 'Bestiaire 2.0 › ligne 17026');
