INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-verre#carte:golem-de-verre-ii', 4, NULL, NULL, 'Grande créature', 'Cette créature est bien plus grande que les autres, ainsi les malus de visée des ennemis sont réduits de moitié. Chaque attaque physique prodiguée par la créature force un jet de stabilité/réflexe pour ne pas être repoussé de 1d4 cases en arrière et tomber au sol.', 'monstres', 'Bestiaire 2.0 › ligne 17821');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-verre#carte:golem-de-verre-ii', 5, NULL, NULL, 'Fait de verre', 'Cette créature possède énormément de résistances magiques mais possède une forte vulnérabilité contre les dégâts sonores.', 'monstres', 'Bestiaire 2.0 › ligne 17821');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-verre#carte:golem-de-verre-ii', 6, NULL, NULL, 'Verre pilé', 'A chaque coup physique encaissé, des éclats de verre sont envoyés à l’attaquant, infligeant 3d6 dégâts neutre.', 'monstres', 'Bestiaire 2.0 › ligne 17821');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-verre#carte:golem-de-verre-ii', 7, NULL, NULL, 'Réflexion du verre', 'Cette créature de renvoyer les dégâts/effets magiques ou physiques de l’élément lumière, en plus de ne prendre aucun dégâts.', 'monstres', 'Bestiaire 2.0 › ligne 17821');
