INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/griffon#carte:grand-griffon', 1, NULL, NULL, 'Vol', 'Cette créature est capable de voler et donc d’ignorer les terrains négatifs.', 'monstres', 'Bestiaire 2.0 › ligne 18758');
