INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/griffon#carte:griffon-royale', 7, NULL, NULL, 'Riposte colérique', 'Chaque contre-attaque augmente ses dégâts de +2 pendant 1 tour (cumulable).', 'monstres', 'Bestiaire 2.0 › ligne 18820');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/griffon#carte:griffon-royale', 8, NULL, NULL, 'Maître des cieux', 'Cette créature est totalement immunisée à la magie du Vent et de la Foudre.', 'monstres', 'Bestiaire 2.0 › ligne 18820');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/hallebarde-amochee#carte:cuirasse-abime', 1, NULL, NULL, 'Mourir peut attendre', 'Cette créature n’a que la moitié de sa santé qu’elle est censée avoir. Quand elle tombe en dessous de 0 santé, elle sombre dans une mort temporaire qui ne dure qu’un tour, à la fin de ce dernier, elle revient avec toute sa santé et barrière. La deuxième mort est fatale par contre.', 'monstres', 'Bestiaire 2.0 › ligne 18897');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/hallebarde-amochee#carte:cuirasse-abime', 2, NULL, NULL, 'Vol', 'Cette créature est capable de voler et donc d’ignorer les terrains négatifs.', 'monstres', 'Bestiaire 2.0 › ligne 18897');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/hallebarde-amochee#carte:cuirasse-abime', 3, NULL, NULL, 'Devoir de l''Arrière', 'Cette créature est ingénieuse, elle est capable de faire un balayage devant elle avec son arme en échange de 15% de réussite pour pouvoir toucher 3 cibles en 1 coup et de taper avec son arme qui dispose d’une portée de 1-3. Elle ne peut pas être désarmer.', 'monstres', 'Bestiaire 2.0 › ligne 18897');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/herbe-folle#carte:herbe-folle-2-yeux', 1, NULL, NULL, 'Rassemblement', 'Cette créature est capable de fusionner avec une autre de la même espèce pour devenir la version mini-boss (si c’était des ennemis simples) ou boss (si c’était des mini-boss)', 'monstres', 'Bestiaire 2.0 › ligne 18965');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/herbe-folle#carte:herbe-folle-2-yeux', 2, NULL, NULL, 'Broussaille', 'Cette créature perd un cran de résistance au Feu et à la Glace, n’aggrave pas les faiblesses.', 'monstres', 'Bestiaire 2.0 › ligne 18965');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/herbe-folle#carte:herbe-folle-2-yeux', 3, NULL, NULL, 'Magie aléatoire', 'Cette créature commence avec une magie aléatoire, le mj le détermine au dé (ou bien de lui-même). Elle peut lancer des sorts selon son niveau.', 'monstres', 'Bestiaire 2.0 › ligne 18965');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/herbe-folle#carte:herbe-folle-3-yeux', 1, NULL, NULL, 'Rassemblement', 'Cette créature est capable de fusionner avec une autre de la même espèce pour devenir la version mini-boss (si c’était des ennemis simples) ou boss (si c’était des mini-boss)', 'monstres', 'Bestiaire 2.0 › ligne 19013');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/herbe-folle#carte:herbe-folle-3-yeux', 2, NULL, NULL, 'Broussaille', 'Cette créature perd un cran de résistance au Feu et à la Glace, n’aggrave pas les faiblesses.', 'monstres', 'Bestiaire 2.0 › ligne 19013');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/herbe-folle#carte:herbe-folle-3-yeux', 3, NULL, NULL, 'Magie aléatoire', 'Cette créature commence avec une magie aléatoire, le mj le détermine au dé (ou bien de lui-même). Elle peut lancer des sorts selon son niveau.', 'monstres', 'Bestiaire 2.0 › ligne 19013');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/herbe-folle#carte:herbe-folle-3-yeux', 4, NULL, NULL, 'Pilonnage', 'Lorsqu’un sort frappe une cible de même magie, sa résistance s’affaiblit d’un cran juste pour l’attaque.', 'monstres', 'Bestiaire 2.0 › ligne 19013');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/herbe-folle#carte:herbe-folle-4-yeux', 1, NULL, NULL, 'Rassemblement', 'Cette créature est capable de fusionner avec une autre de la même espèce pour devenir la version mini-boss (si c’était des ennemis simples) ou boss (si c’était des mini-boss)', 'monstres', 'Bestiaire 2.0 › ligne 19064');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/herbe-folle#carte:herbe-folle-4-yeux', 2, NULL, NULL, 'Broussaille', 'Cette créature perd un cran de résistance au Feu et à la Glace, n’aggrave pas les faiblesses.', 'monstres', 'Bestiaire 2.0 › ligne 19064');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/herbe-folle#carte:herbe-folle-4-yeux', 3, NULL, NULL, 'Magie aléatoire', 'Cette créature commence avec une magie aléatoire, le mj le détermine au dé (ou bien de lui-même). Elle peut lancer des sorts selon son niveau.', 'monstres', 'Bestiaire 2.0 › ligne 19064');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/herbe-folle#carte:herbe-folle-4-yeux', 4, NULL, NULL, 'Pilonnage', 'Lorsqu’un sort frappe une cible de même magie, sa résistance s’affaiblit d’un cran.', 'monstres', 'Bestiaire 2.0 › ligne 19064');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/herbe-folle#carte:herbe-folle-4-yeux', 5, NULL, NULL, 'Acharnement', 'Lorsqu’un sort frappe une cible de magie vulnérable, sa faiblesse s’aggrave d’un cran juste pour l’attaque.', 'monstres', 'Bestiaire 2.0 › ligne 19064');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/irapullum#carte:irapullum', 1, NULL, NULL, 'Grande créature', 'Cette créature est bien plus grande que les autres, ainsi les malus de visée des ennemis sont réduits de moitié. Chaque attaque physique prodiguée par la créature force un jet de stabilité pour ne pas être repoussé de 1d4 cases en arrière et tomber au sol.', 'monstres', 'Bestiaire 2.0 › ligne 19131');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/irapullum#carte:irapullum', 2, NULL, NULL, 'Attaque sanglante', 'Les armes naturelles de cette créature obligent le jet de vigueur pour ne pas prendre “Saignement 1”.', 'monstres', 'Bestiaire 2.0 › ligne 19131');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/irapullum#carte:irapullum-sanglant', 1, NULL, NULL, 'Grande créature', 'Cette créature est bien plus grande que les autres, ainsi les malus de visée des ennemis sont réduits de moitié. Chaque attaque physique prodiguée par la créature force un jet de stabilité pour ne pas être repoussé de 1d4 cases en arrière et tomber au sol.', 'monstres', 'Bestiaire 2.0 › ligne 19187');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/irapullum#carte:irapullum-sanglant', 2, NULL, NULL, 'Attaque sanglante', 'Les armes naturelles de cette créature obligent le jet de vigueur pour ne pas prendre “Saignement 1”.', 'monstres', 'Bestiaire 2.0 › ligne 19187');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/irapullum#carte:irapullum-sanglant', 3, NULL, NULL, 'Psychotique', 'Réussir à infliger saignement à sa cible provoque une frénésie qui permet d''attaquer une seconde fois (1 fois/2 tours).', 'monstres', 'Bestiaire 2.0 › ligne 19187');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/irapullum#carte:irapullum-vorace', 1, NULL, NULL, 'Grande créature', 'Cette créature est bien plus grande que les autres, ainsi les malus de visée des ennemis sont réduits de moitié. Chaque attaque physique prodiguée par la créature force un jet de stabilité pour ne pas être repoussé de 1d4 cases en arrière et tomber au sol.', 'monstres', 'Bestiaire 2.0 › ligne 19244');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/irapullum#carte:irapullum-vorace', 2, NULL, NULL, 'Attaque sanglante', 'Les armes naturelles de cette créature obligent le jet de vigueur pour ne pas prendre “Saignement 1”.', 'monstres', 'Bestiaire 2.0 › ligne 19244');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/irapullum#carte:irapullum-vorace', 3, NULL, NULL, 'Psychotique', 'Réussir à infliger saignement à sa cible provoque une frénésie qui permet d''attaquer une seconde fois (1 fois/tour).', 'monstres', 'Bestiaire 2.0 › ligne 19244');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/irapullum#carte:irapullum-vorace', 4, NULL, NULL, 'Sang variable', 'Cette créature est capable d’utiliser tous les sorts “sang” de la magie du sang en plus de pouvoir les utiliser sans avoir de jet. (IC) (coût = 10 santé) (n’a pas accès au “Sang perfection”).', 'monstres', 'Bestiaire 2.0 › ligne 19244');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/jambieres-moisies#carte:jambieres-moisies', 1, NULL, NULL, 'Mourir peut attendre', 'Cette créature n’a que la moitié de sa santé qu’elle est censée avoir. Quand elle tombe en dessous de 0 santé, elle sombre dans une mort temporaire qui ne dure qu’un tour, à la fin de ce dernier, elle revient avec toute sa santé et barrière. La deuxième mort est fatale par contre.', 'monstres', 'Bestiaire 2.0 › ligne 19315');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/jambieres-moisies#carte:jambieres-moisies', 2, NULL, NULL, 'Vol', 'Cette créature est capable de voler et donc d’ignorer les terrains négatifs.', 'monstres', 'Bestiaire 2.0 › ligne 19315');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/jambieres-moisies#carte:jambieres-moisies', 3, NULL, NULL, 'Devoir de l’Exécuteur', 'Cette créature est vicieuse, elle dispose d’un bonus à la vitesse de +1, à l’Initiative de +4, elle est capable d’attaque sournoise qui lui donne un bonus de 1d8 dégâts en plus de son arme. Elle est également capable de passer dans les zones d’influences sans déclencher des attaques d’opportunités.', 'monstres', 'Bestiaire 2.0 › ligne 19315');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/karn#carte:chef-de-guerre-karn', 1, NULL, NULL, 'Perce armure', 'L’attaque de cette créature perce 3 AP.', 'monstres', 'Bestiaire 2.0 › ligne 19500');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/karn#carte:chef-de-guerre-karn', 2, NULL, NULL, 'Fermeté', 'Cette créature ne subit aucun dégâts de recul et inflige un bonus de +5 dégâts si elle fait une attaque suivie d’un déplacement qui a consommé toute sa vitesse.', 'monstres', 'Bestiaire 2.0 › ligne 19500');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/karn#carte:chef-de-guerre-karn', 3, NULL, NULL, 'Destruction', 'Le coup critique de cette créature retire automatiquement un cran de solidité à l’arme ou morceau d’armure.', 'monstres', 'Bestiaire 2.0 › ligne 19500');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/karn#carte:chef-de-guerre-karn', 4, NULL, NULL, 'Soif de combat', 'Quand cette créature tombe en dessous de 75% de santé, +3 aux dégâts. En dessous de 50%, +5 aux dégâts. En dessous de 25%, +7 aux dégâts.', 'monstres', 'Bestiaire 2.0 › ligne 19500');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/karn#carte:chef-de-guerre-karn', 5, NULL, NULL, 'Élément aléatoire', 'Cette créature peut être de différentes formes et possède un bonus différent selon la magie auquel il est relié. Et avec tout ça, une de ses armes* naturelles est capable d''infliger l’élément relié.
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/karn#carte:jeune-karn', 1, NULL, NULL, 'Perce armure', 'L’attaque de cette créature perce 3 AP.', 'monstres', 'Bestiaire 2.0 › ligne 19375');
