INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/loup-garou#carte:loup-garou', 1, NULL, NULL, 'Haine mutuelle', 'Cette créature inflige un bonus +10 dégâts contre les Fenrirs mais ces derniers ont également le même bonus sur cette première.', 'monstres', 'Bestiaire 2.0 › ligne 19689');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/loup-garou#carte:loup-garou', 2, NULL, NULL, 'Triumvirat instable fenrir', 'Cette créature est liée aux magies de la Foudre, Glace et Ombre et est capable d’utiliser ces magies selon son niveau. Mais les faiblesses aux altérations d’états s’en trouvent amplifiées.', 'monstres', 'Bestiaire 2.0 › ligne 19689');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/loup-garou#carte:loup-garou', 3, '[EP2]', 2, 'Bond', 'Cette créature est capable de faire un bond équivalent à sa vitesse x2 en échange de 3IC.', 'monstres', 'Bestiaire 2.0 › ligne 19689');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/loup-garou#carte:loup-garou', 4, '[EP3]', 3, 'Issue de l’éclair', 'Immunisé à la paralysie.', 'monstres', 'Bestiaire 2.0 › ligne 19689');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/loup-garou#carte:loup-garou', 5, '[EP4]', 4, 'Lame canine', 'Les dégâts de taille ont un bonus de +8 aux dégâts.', 'monstres', 'Bestiaire 2.0 › ligne 19689');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/loup-garou#carte:loup-garou', 6, '[EP5]', 5, 'Aura d’ombre', 'Permet d''annuler totalement une frappe de l’élément lumière, que ce soit dégâts ou effets secondaires. (Réaction 1 fois/combat)', 'monstres', 'Bestiaire 2.0 › ligne 19689');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/loup-garou#carte:loup-garou', 7, '[EP6]', 6, 'Rayon Lune', 'Régénère 25% de la barrière la nuit. (Action 2 fois/nuit)', 'monstres', 'Bestiaire 2.0 › ligne 19689');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/loup-garou#carte:loup-garou', 8, '[EP7]', 7, 'Magicien', 'Les dégâts de Glace, Ombre et de Foudre augmentent de +10.', 'monstres', 'Bestiaire 2.0 › ligne 19689');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/loup-garou#carte:loup-garou', 9, '[EP8]', 8, 'Aura lunaire', 'Réduit les dégâts de glace, feu, lumière et ombre de 6.', 'monstres', 'Bestiaire 2.0 › ligne 19689');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/loup-garou#carte:loup-garou', 10, '[EP9]', 9, 'Hurlement', 'Les alliés à 3 cases gagnent +4 à leur dégâts pendant 3 tours. Permet de donner des ordres précis à une créature canine alliée. (Action 1 fois/combat)', 'monstres', 'Bestiaire 2.0 › ligne 19689');
