INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/loup-garou#carte:loup-garou-abominable', 12, '[EP9]', 9, 'Cri d''Alpha', 'Oblige les adversaires à faire un jet de calme pour ne pas perdre 1 tour. Les créatures canines non apprivoisées fuient automatiquement. (Action 1 fois/combat)', 'monstres', 'Bestiaire 2.0 › ligne 19930');
