INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/loup-garou#carte:loup-garou-superieur', 6, '[EP4]', 4, 'Aura d’ombre', 'Permet d''annuler totalement une frappe de l’élément lumière, que ce soit dégâts ou effets secondaires. (Réaction 1 fois/combat)', 'monstres', 'Bestiaire 2.0 › ligne 19808');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/loup-garou#carte:loup-garou-superieur', 7, '[EP5]', 5, 'Rayon Lune', 'Régénère 25% de la barrière la nuit. (Action 2 fois/nuit)', 'monstres', 'Bestiaire 2.0 › ligne 19808');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/loup-garou#carte:loup-garou-superieur', 8, '[EP6]', 6, 'Magicien', 'Les dégâts de Glace, Ombre et de Foudre augmentent de +10.', 'monstres', 'Bestiaire 2.0 › ligne 19808');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/loup-garou#carte:loup-garou-superieur', 9, '[EP7]', 7, 'Aura lunaire', 'Réduit les dégâts de glace, feu, lumière et ombre de 6.', 'monstres', 'Bestiaire 2.0 › ligne 19808');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/loup-garou#carte:loup-garou-superieur', 10, '[EP8]', 8, 'Hurlement', 'Les alliés à 3 cases gagnent +4 à leur dégâts pendant 3 tours. Permet de donner des ordres précis à une créature canine alliée. (Action 1 fois/combat)', 'monstres', 'Bestiaire 2.0 › ligne 19808');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/loup-garou#carte:loup-garou-superieur', 11, '[EP9]', 9, 'Super Odorat', 'Cette créature ne peut pas avoir de croix à la Perception.', 'monstres', 'Bestiaire 2.0 › ligne 19808');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/loup-garou#carte:loup-garou-superieur', 12, '[EP10]', 10, 'Cri d''Alpha', 'Oblige les adversaires à faire un jet de calme pour ne pas perdre 1 tour. Les créatures canines non apprivoisées fuient automatiquement. (Action 1 fois/combat)', 'monstres', 'Bestiaire 2.0 › ligne 19808');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/lumiphage#carte:lumiphage-paladin', 1, NULL, NULL, 'Non-Mort', 'Une créature non-mort est immunisée à la peur, à la couardise, à la fatigue, au poison, à la maladie. Les soins de lumière lui infligent des dégâts mais il a la possibilité de faire un jet de défense pour ne pas prendre les dégâts.', 'monstres', 'Bestiaire 2.0 › ligne 20200');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/lumiphage#carte:lumiphage-paladin', 2, NULL, NULL, 'Squelettique', 'Rend cette créature immunisé aux attaques d’estoc', 'monstres', 'Bestiaire 2.0 › ligne 20200');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/lumiphage#carte:lumiphage-paladin', 3, NULL, NULL, 'Soin non-mort', 'Cette créature est capable de soigner ses alliés non-morts avec la magie de la lumière.', 'monstres', 'Bestiaire 2.0 › ligne 20200');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/lumiphage#carte:lumiphage-paladin', 4, NULL, NULL, 'Tome de Lumière lvl4', 'Permet à cette créature de lancer des sorts de la magie de la Lumière au niveau 4 de puissance.', 'monstres', 'Bestiaire 2.0 › ligne 20200');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/lumiphage#carte:lumiphage-paladin', 5, NULL, NULL, 'Anti-mal', 'Inflige un bonus de +8 dégâts contre les créatures mauvaises.', 'monstres', 'Bestiaire 2.0 › ligne 20200');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/lumiphage#carte:lumiphage-paladin', 6, NULL, NULL, 'Rayon d’Aurora', 'Invoque “Grand Soleil” dès le début du combat.', 'monstres', 'Bestiaire 2.0 › ligne 20200');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/lumiphage#carte:lumiphage-paladin', 7, NULL, NULL, 'Climatoptimiste', 'Double les effets positifs de la météo pour lui et ses alliés.', 'monstres', 'Bestiaire 2.0 › ligne 20200');
