INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/luperoc#carte:luperoc-adulte', 1, NULL, NULL, 'Esprit de meute', 'Cette créature gagne un bonus de +5% à tous ses jets par alliés dans une zone de 2 cases autour de lui.', 'monstres', 'Bestiaire 2.0 › ligne 20325');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/luperoc#carte:luperoc-adulte', 2, NULL, NULL, 'Terrain avantageux', 'Si cette créature est dans un terrain qui lui est favorable = +2 à la réussite critique et +3 aux dégâts. (Terrain favorable = Forêt, Plateau, Montagne)', 'monstres', 'Bestiaire 2.0 › ligne 20325');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/luperoc#carte:luperoc-adulte', 3, NULL, NULL, 'Fourrure de roche', 'Cette créature est capable d’augmenter ses AP de 5 pendant 3 tours. (IC - 1 fois/combat)', 'monstres', 'Bestiaire 2.0 › ligne 20325');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/luperoc#carte:luperoc-alpha', 1, NULL, NULL, 'Terrain avantageux', 'Si cette créature est dans un terrain qui lui est favorable = +2 à la réussite critique et +3 aux dégâts. (Terrain favorable = Forêt, Plateau, Montagne)', 'monstres', 'Bestiaire 2.0 › ligne 20379');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/luperoc#carte:luperoc-alpha', 2, NULL, NULL, 'Fourrure de roche', 'Cette créature est capable d’augmenter ses AP de 5 pendant 3 tours. (IC - 1 fois/combat)', 'monstres', 'Bestiaire 2.0 › ligne 20379');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/luperoc#carte:luperoc-alpha', 3, NULL, NULL, 'Lanceur de sorts', 'Cette créature peut lancer les sorts, avec les niveaux de maîtrises maximum : Explosion rocheuse, Infection, Fer raffiné.', 'monstres', 'Bestiaire 2.0 › ligne 20379');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/luperoc#carte:luperoc-jeune', 1, NULL, NULL, 'Esprit de meute', 'Cette créature gagne un bonus de +5% à tous ses jets par alliés dans une zone de 2 cases autour de lui.', 'monstres', 'Bestiaire 2.0 › ligne 20274');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/luperoc#carte:luperoc-jeune', 2, NULL, NULL, 'Terrain avantageux', 'Si cette créature est dans un terrain qui lui est favorable = +2 à la réussite critique et +3 aux dégâts. (Terrain favorable = Forêt, Plateau, Montagne)', 'monstres', 'Bestiaire 2.0 › ligne 20274');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/main-blanche#carte:main-blanche', 1, NULL, NULL, 'Calque amitié/amour', 'Cette créature est capable de calquer les capacités d’une créature que sa cible affectionne dans son cœur en se métamorphosant en cette dernière. La métamorphose cesse quand l’adversaire est dans le coma ou quand le métamorphe tombe en dessous de 50% de santé (elle copie les carac, compétences, don, race, classe, magie mais garde ses attributs)', 'monstres', 'Bestiaire 2.0 › ligne 20433');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/main-blanche#carte:main-blanche', 2, NULL, NULL, 'Super barrière', 'Cette créature possède une barrière qui correspond à son chakra.', 'monstres', 'Bestiaire 2.0 › ligne 20433');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/main-blanche#carte:main-blanche', 3, NULL, NULL, 'Attendrissement', 'En échange de 3IC, cette créature peut forcer le jet de fermeté à sa cible, si cette dernière rate, elle ne peut pas attaquer à son prochain tour. (recharge de 3 tours)', 'monstres', 'Bestiaire 2.0 › ligne 20433');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/masse-empoisonneuse#carte:masse-empoisonneuse', 1, NULL, NULL, 'Attaque poison', 'Les armes de cette créature obligent un jet de vigueur à la cible, si cette dernière rate, elle se prend “Poison 1”', 'monstres', 'Bestiaire 2.0 › ligne 20499');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/masse-empoisonneuse#carte:masse-empoisonneuse', 2, NULL, NULL, 'Critique venimeuse', 'Une attaque en réussite critique va automatiquement infliger le stade 1 d’empoisonnement à la victime jusqu’au prochain remède, et ceux peu importe les résistances de la cible (sauf immunité).', 'monstres', 'Bestiaire 2.0 › ligne 20499');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/masse-empoisonneuse#carte:masse-empoisonneuse', 3, NULL, NULL, 'Attrape moi', 'Les jets de défense possèdent un bonus de 5% par ennemi empoisonné sur le terrain (maximum 20%).', 'monstres', 'Bestiaire 2.0 › ligne 20499');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/molvacier#carte:molvacier-adulte', 1, NULL, NULL, 'Aveugle naturel', 'Cette créature est naturellement aveugle, ce qui l''immunise de tous les effets, attaques ou altérations d’état lié à la vue. Cet aveuglement ne l’empêche pas de connaître son environnement et de savoir où sont ses ennemis, la Perception n’est donc pas endommagée.', 'monstres', 'Bestiaire 2.0 › ligne 20622');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/molvacier#carte:molvacier-adulte', 2, NULL, NULL, 'Fouisseur', 'Cette créature peut plonger dans le sol pour attaquer par le bas une autre, ça lui demande un tour complet pour pouvoir attaquer mais bénéficie d’un bonus de +5 dégâts quand l’attaque fait mouche.', 'monstres', 'Bestiaire 2.0 › ligne 20622');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/molvacier#carte:molvacier-adulte', 3, NULL, NULL, 'Perce muraille', 'L’attaque de cette créature perce 6 AP.', 'monstres', 'Bestiaire 2.0 › ligne 20622');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/molvacier#carte:molvacier-adulte', 4, NULL, NULL, 'Tremblement', 'Dans le sol, cette créature fait remuer le sol si fort qu’elle force un jet de stabilité à sa cible pour ne pas qu’elle tombe par terre.', 'monstres', 'Bestiaire 2.0 › ligne 20622');
