INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/momie#carte:momie', 2, NULL, NULL, 'Attaque maudite', 'L’une des armes* de cette créature possède l’effet du sort “Malédiction” de la magie de l’ombre et l’impose pour 1 tour à la victime.', 'monstres', 'Bestiaire 2.0 › ligne 20822');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/momie#carte:momie', 3, NULL, NULL, 'Anti-chaos', 'Cette créature inflige +5 dégâts contre les créatures chaotiques.', 'monstres', 'Bestiaire 2.0 › ligne 20822');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/momie#carte:momie', 4, NULL, NULL, 'Maître du silence', 'Cette créature ne peut pas subir les sorts ou effets qui empêche d’utiliser la magie.', 'monstres', 'Bestiaire 2.0 › ligne 20822');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/momie#carte:momie', 5, NULL, NULL, 'Lanceur de sorts', 'Cette créature peut lancer les sorts, avec les niveaux de maîtrises maximum : Téléportation, Faille temporelle, Frappe temporelle, Vieillissement.', 'monstres', 'Bestiaire 2.0 › ligne 20822');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/momie#carte:momie', 6, NULL, NULL, 'Concentration coloré', 'Utilise la concentration au lieu de la magie pour lancer ses sorts.', 'monstres', 'Bestiaire 2.0 › ligne 20822');
