INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/momie#carte:momie-royale', 5, NULL, NULL, 'Lanceur de sorts', 'Cette créature peut lancer les sorts, avec les niveaux de maîtrises maximum : Téléportation, Faille temporelle, Frappe temporelle, Vieillissement, Horloge aspirante, Inversion.', 'monstres', 'Bestiaire 2.0 › ligne 20956');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/momie#carte:momie-royale', 6, NULL, NULL, 'Concentration coloré', 'Utilise la concentration au lieu de la magie pour lancer ses sorts.', 'monstres', 'Bestiaire 2.0 › ligne 20956');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/momie#carte:momie-royale', 7, NULL, NULL, 'Sulfateuse', 'Les arbalètes n’ont plus de recharge longue.', 'monstres', 'Bestiaire 2.0 › ligne 20956');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/momie#carte:momie-royale', 8, NULL, NULL, 'Corps précieux', 'Le matériau Argent ne possède pas son bonus de dégâts contre cette créature.', 'monstres', 'Bestiaire 2.0 › ligne 20956');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/momie#carte:momie-surveillante', 1, NULL, NULL, 'Non-Mort', 'Une créature non-mort est immunisée à la peur, à la couardise, à la fatigue, au poison, à la maladie. Les soins de lumière lui infligent des dégâts mais il a la possibilité de faire un jet de défense pour ne pas prendre les dégâts.', 'monstres', 'Bestiaire 2.0 › ligne 20889');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/momie#carte:momie-surveillante', 2, NULL, NULL, 'Attaque maudite', 'L’une des armes* de cette créature possède l’effet du sort “Malédiction” de la magie de l’ombre et l’impose pour 1 tour à la victime.', 'monstres', 'Bestiaire 2.0 › ligne 20889');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/momie#carte:momie-surveillante', 3, NULL, NULL, 'Anti-chaos', 'Cette créature inflige +5 dégâts contre les créatures chaotiques.', 'monstres', 'Bestiaire 2.0 › ligne 20889');
