INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/mordor#carte:mordor-chasseur', 1, NULL, NULL, 'Non-Mort', 'Une créature non-mort est immunisée à la peur, à la couardise, à la fatigue, au poison, à la maladie. Les soins de lumière lui infligent des dégâts mais il a la possibilité de faire un jet de défense pour ne pas prendre les dégâts.', 'monstres', 'Bestiaire 2.0 › ligne 21159');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/mordor#carte:mordor-chasseur', 2, NULL, NULL, 'Grande créature', 'Cette créature est bien plus grande que les autres, ainsi les malus de visée des ennemis sont réduits de moitié. Chaque attaque physique prodiguée par la créature force un jet de stabilité pour ne pas être repoussé de 1d4 cases en arrière et tomber au sol.', 'monstres', 'Bestiaire 2.0 › ligne 21159');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/mordor#carte:mordor-chasseur', 3, NULL, NULL, 'Charge sans peur', 'Permet d''avoir un bonus de +7 au jet d''initiative.', 'monstres', 'Bestiaire 2.0 › ligne 21159');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/mordor#carte:mordor-chasseur', 4, NULL, NULL, 'Cord’or', 'Cette créature est immunisée à toutes les altérations, à tous les sorts qui ne causent pas de dégâts.', 'monstres', 'Bestiaire 2.0 › ligne 21159');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/mordor#carte:mordor-chasseur', 5, NULL, NULL, 'Vise le trésor', 'Cette créature va se concentrer sur les adversaires les plus “riches”.', 'monstres', 'Bestiaire 2.0 › ligne 21159');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/mordor#carte:mordor-chasseur', 6, NULL, NULL, 'Lanceur de sorts', 'Cette créature peut lancer les sorts, avec les niveaux de maîtrises maximum : Éclair en chaîne, Anti-Mythril, Rayon négatif, Poison de masse.', 'monstres', 'Bestiaire 2.0 › ligne 21159');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/mordor#carte:mordor-chasseur', 7, NULL, NULL, 'Arnaque défensif', 'Peut convertir ses AP en dégâts physiques et ses AM en dégâts magiques pendant 3 tours.', 'monstres', 'Bestiaire 2.0 › ligne 21159');
