INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/noye#carte:noye', 3, NULL, NULL, 'Vomi', 'La créature vomi une espèce d’acide qui va s’infiltrer dans les armures ou vêtements et brûler la peau. Inflige pendant 2 tours 2d6 dégâts perce armure et va retirer un cran de solidité au morceau d’armure touché (une seule fois).', 'monstres', 'Bestiaire 2.0 › ligne 21530');
