INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/ogre#carte:ogre', 1, NULL, NULL, 'Haine mutuelle', 'Cette créature inflige un bonus +10 dégâts contre les Marcass mais ces derniers ont également le même bonus sur cette première.', 'monstres', 'Bestiaire 2.0 › ligne 21759');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/ogre#carte:ogre', 2, NULL, NULL, 'Pile ou Face', 'Cette créature dispose de deux façon de se battre, ce qui entraîne de gros changements dans la manière d''appréhender la créature. (Forme : Guerrier/Mage). La créature peut changer de forme au début ou en fin de tour gratuitement.
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/ogre#carte:ogre', 3, NULL, NULL, 'Tome 2 fois 2 couleurs', 'Cette créature dispose de 2 paires de magies qui utilise d’une façon qui lui est propre (voir Pile ou Face). Il utilisera les sorts qui correspondent à son niveau de puissance, il ne peut pas atteindre les sorts niveau 5 de puissance magique.', 'monstres', 'Bestiaire 2.0 › ligne 21759');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/ogre#carte:ogre', 4, '[EP2]', 2, 'Recyclage', 'Manger de la viande avariée ou de mort redonne 2d8 santé.', 'monstres', 'Bestiaire 2.0 › ligne 21759');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/ogre#carte:ogre', 5, '[EP3]', 3, 'Charge porcine', 'Permet d''avoir un bonus de +2 à la vitesse. Possible uniquement en ligne droite et si il y a une cible à l''arrivée.', 'monstres', 'Bestiaire 2.0 › ligne 21759');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/ogre#carte:ogre', 6, '[EP4]', 4, 'Magie et Acier', '+3 aux dégâts des armes et des sorts.', 'monstres', 'Bestiaire 2.0 › ligne 21759');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/ogre#carte:ogre', 7, '[EP5]', 5, 'Critique altérant', 'L’arme de cette créature, sur un coup critique, est capable d''obliger le jet de vigueur/fermeté pour ne pas que la cible prenne l’altération d’état liée à sa magie (aléatoire si elle en a plusieurs)', 'monstres', 'Bestiaire 2.0 › ligne 21759');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/ogre#carte:ogre', 8, '[EP6]', 6, 'Nécrophage', 'Manger de la viande de cadavre redonne 3d8 barrière.', 'monstres', 'Bestiaire 2.0 › ligne 21759');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/ogre#carte:ogre', 9, '[EP7]', 7, 'Face ou Face', 'L’ogre est capable d''activer temporairement ses deux têtes en même temps. Ce qui fait qu’elle combine tous les avantages en défense. Dure 3 tours. (1 fois par combat)', 'monstres', 'Bestiaire 2.0 › ligne 21759');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/ogre#carte:ogre', 10, '[EP8]', 8, 'Phalange', 'L’arme de cette créature ignore l’effet des boucliers.', 'monstres', 'Bestiaire 2.0 › ligne 21759');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/ogre#carte:ogre', 11, '[EP9]', 9, 'Météore', 'Permet de sauter sur une case et infliger -1d dégâts sur une zone de 3x3. (Portée = Vitesse)', 'monstres', 'Bestiaire 2.0 › ligne 21759');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/ogre#carte:ogre', 12, '[EP10]', 10, 'Balayage', 'Permet de sacrifier 35% de réussite pour faire une attaque qui va toucher toutes les cibles autour (y compris en diagonale).', 'monstres', 'Bestiaire 2.0 › ligne 21759');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/ogre#carte:ogre-abominable', 1, NULL, NULL, 'Haine mutuelle', 'Cette créature inflige un bonus +10 dégâts contre les Marcass mais ces derniers ont également le même bonus sur cette première.', 'monstres', 'Bestiaire 2.0 › ligne 22033');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/ogre#carte:ogre-abominable', 2, NULL, NULL, 'Grande créature', 'Cette créature est bien plus grande que les autres, ainsi les malus de visée des ennemis sont réduits de moitié. Chaque attaque physique prodiguée par la créature force un jet de stabilité pour ne pas être repoussé de 1d4 cases en arrière et tomber au sol.', 'monstres', 'Bestiaire 2.0 › ligne 22033');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/ogre#carte:ogre-abominable', 3, NULL, NULL, 'Pile ou Face', 'Cette créature dispose de deux façon de se battre, ce qui entraîne de gros changements dans la manière d''appréhender la créature. (Forme : Guerrier/Mage). La créature peut changer de forme au début ou en fin de tour gratuitement.
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/ogre#carte:ogre-abominable', 4, NULL, NULL, 'Tome 2 fois 2 couleurs', 'Cette créature dispose de 2 paires de magies qui utilise d’une façon qui lui est propre (voir Pile ou Face). Il utilisera les sorts qui correspondent à son niveau de puissance, il ne peut pas atteindre les sorts niveau 5 de puissance magique.', 'monstres', 'Bestiaire 2.0 › ligne 22033');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/ogre#carte:ogre-abominable', 5, NULL, NULL, 'Recyclage', 'Manger de la viande avariée ou de mort redonne 2d8 santé.', 'monstres', 'Bestiaire 2.0 › ligne 22033');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/ogre#carte:ogre-abominable', 6, NULL, NULL, 'Charge porcine', 'Permet d''avoir un bonus de +2 à la vitesse. Possible uniquement en ligne droite et si il y a une cible à l''arrivée.', 'monstres', 'Bestiaire 2.0 › ligne 22033');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/ogre#carte:ogre-abominable', 7, '[EP2]', 2, 'Magie et Acier', '+3 aux dégâts des armes et des sorts.', 'monstres', 'Bestiaire 2.0 › ligne 22033');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/ogre#carte:ogre-abominable', 8, '[EP3]', 3, 'Critique altérant', 'L’arme de cette créature, sur un coup critique, est capable d''obliger le jet de vigueur/fermeté pour ne pas que la cible prenne l’altération d’état liée à sa magie (aléatoire si elle en a plusieurs)', 'monstres', 'Bestiaire 2.0 › ligne 22033');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/ogre#carte:ogre-abominable', 9, '[EP4]', 4, 'Nécrophage', 'Manger de la viande de cadavre redonne 3d8 barrière.', 'monstres', 'Bestiaire 2.0 › ligne 22033');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/ogre#carte:ogre-abominable', 10, '[EP5]', 5, 'Face ou Face', 'L’ogre est capable d''activer temporairement ses deux têtes en même temps. Ce qui fait qu’elle combine tous les avantages en défense. Dure 3 tours. (1 fois par combat)', 'monstres', 'Bestiaire 2.0 › ligne 22033');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/ogre#carte:ogre-abominable', 11, '[EP6]', 6, 'Phalange', 'L’arme de cette créature ignore l’effet des boucliers.', 'monstres', 'Bestiaire 2.0 › ligne 22033');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/ogre#carte:ogre-abominable', 12, '[EP7]', 7, 'Météore', 'Permet de sauter sur une case et infliger -1d dégâts sur une zone de 3x3. (Portée = Vitesse)', 'monstres', 'Bestiaire 2.0 › ligne 22033');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/ogre#carte:ogre-abominable', 13, '[EP8]', 8, 'Balayage', 'Permet de sacrifier 35% de réussite pour faire une attaque qui va toucher toutes les cibles autour (y compris en diagonale).', 'monstres', 'Bestiaire 2.0 › ligne 22033');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/ogre#carte:ogre-abominable', 14, '[EP9]', 9, 'Surpuissance', 'Pendant le “Face et Face”, la créature obtient un bonus de +7 à tous les dégâts.', 'monstres', 'Bestiaire 2.0 › ligne 22033');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/ogre#carte:ogre-abominable', 15, '[EP10]', 10, 'Surtension', 'Pendant le “Face et Face”, la créature est capable de lancer des sorts niveau 5 de puissance et ce premier dure 1 tour de plus.', 'monstres', 'Bestiaire 2.0 › ligne 22033');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/ogre#carte:ogre-superieur', 1, NULL, NULL, 'Haine mutuelle', 'Cette créature inflige un bonus +10 dégâts contre les Marcass mais ces derniers ont également le même bonus sur cette première.', 'monstres', 'Bestiaire 2.0 › ligne 21897');
