INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/orc#carte:orc', 1, NULL, NULL, 'Haine mutuelle', 'Cette créature inflige un bonus +10 dégâts contre les Elfes forestiers mais ces derniers ont également le même bonus sur cette première.', 'monstres', 'Bestiaire 2.0 › ligne 22172');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/orc#carte:orc', 2, NULL, NULL, 'Magie aléatoire', 'Cette créature commence avec une magie aléatoire, le mj le détermine au dé (ou bien de lui-même). Elle peut lancer des sorts selon son niveau.', 'monstres', 'Bestiaire 2.0 › ligne 22172');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/orc#carte:orc', 3, NULL, NULL, 'Nerveux', 'Cette créature à +4 à l’initiative.', 'monstres', 'Bestiaire 2.0 › ligne 22172');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/orc#carte:orc', 4, '[EP2]', 2, 'Mimique', 'Imite le jet de l''agresseur lors d''un combat. Si c''est une réussite critique, un jet de chance est nécessaire. (2 fois/combat)', 'monstres', 'Bestiaire 2.0 › ligne 22172');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/orc#carte:orc', 5, '[EP3]', 3, 'Doublette parfaite', 'Les malus pour toucher avec deux armes descend respectivement à 10% pour la première arme et 20% pour la seconde arme.', 'monstres', 'Bestiaire 2.0 › ligne 22172');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/orc#carte:orc', 6, '[EP4]', 4, 'Sournois', 'Quand l''adversaire n''est pas attentif au personnage, permet d''infliger un bonus de 2d4 dégâts en plus des dégâts de l''arme.', 'monstres', 'Bestiaire 2.0 › ligne 22172');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/orc#carte:orc', 7, '[EP5]', 5, 'Charge sans peur', 'Le bonus à l’initiative passe à +7.', 'monstres', 'Bestiaire 2.0 › ligne 22172');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/orc#carte:orc', 8, '[EP6]', 6, 'Mimétisme', 'Capable de copier un don d’une classe d’un adversaire si il a été enclenché.', 'monstres', 'Bestiaire 2.0 › ligne 22172');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/orc#carte:orc', 9, '[EP7]', 7, 'Bond', 'Cette créature est capable de faire un bond équivalent à sa vitesse x2 en échange de 3IC.', 'monstres', 'Bestiaire 2.0 › ligne 22172');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/orc#carte:orc', 10, '[EP8]', 8, 'Prédaforêt', 'Tant que cette créature est en milieu forestier = +1% à la réussite critique.', 'monstres', 'Bestiaire 2.0 › ligne 22172');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/orc#carte:orc', 11, '[EP9]', 9, 'Équilibré', 'Réduit de 5% le malus de la deuxième arme.', 'monstres', 'Bestiaire 2.0 › ligne 22172');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/orc#carte:orc', 12, '[EP10]', 10, 'Vraiment sournois', 'L’attaque sournoise passe à 4d4.', 'monstres', 'Bestiaire 2.0 › ligne 22172');
