INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/os-du-froid#carte:os-du-blizzard', 1, NULL, NULL, 'Non-Mort', 'Une créature non-mort est immunisée à la peur, à la couardise, à la fatigue, au poison, à la maladie. Les soins de lumière lui infligent des dégâts mais il a la possibilité de faire un jet de défense pour ne pas prendre les dégâts.', 'monstres', 'Bestiaire 2.0 › ligne 22701');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/os-du-froid#carte:os-du-blizzard', 2, NULL, NULL, 'Squelettique', 'Rend cette créature immunisé aux attaques d’estoc', 'monstres', 'Bestiaire 2.0 › ligne 22701');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/os-du-froid#carte:os-du-blizzard', 3, NULL, NULL, 'Charge sans peur', 'Permet d''avoir un bonus de +7 au jet d''initiative.', 'monstres', 'Bestiaire 2.0 › ligne 22701');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/os-du-froid#carte:os-du-blizzard', 4, NULL, NULL, 'Élément Glace', 'L’élément d’attaque de cette créature est la Glace avec 25% de chance d’obliger un jet de vigueur à la cible, si elle rate, elle prend “Gelé 1”.', 'monstres', 'Bestiaire 2.0 › ligne 22701');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/os-du-froid#carte:os-du-blizzard', 5, NULL, NULL, 'Tome de la Glace lvl3', 'Permet à cette créature de lancer des sorts de la magie de la Glace au niveau 3 de puissance.', 'monstres', 'Bestiaire 2.0 › ligne 22701');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/os-du-froid#carte:os-du-blizzard', 6, NULL, NULL, 'Anti alignement', 'Inflige +4 dégâts contre les créatures de la Loi et du Chaos.', 'monstres', 'Bestiaire 2.0 › ligne 22701');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/os-du-froid#carte:os-du-blizzard', 7, NULL, NULL, 'Aucune fuite', 'Si jamais il y a impossibilité de fuir ou qu’un état de peur est tenté contre lui = +5 dégâts, +1 Vitesse le temps que la situation se débloque.', 'monstres', 'Bestiaire 2.0 › ligne 22701');
