INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/ottar-chariot#carte:ottar-chariot', 1, NULL, NULL, 'Ottar', 'Cette créature est un Ottar et est donc totalement invulnérable au contrôle mental, à la peur et à la couardise.', 'monstres', 'Bestiaire 2.0 › ligne 23296');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/ottar-chariot#carte:ottar-chariot', 2, NULL, NULL, 'Grande créature', 'Cette créature est bien plus grande que les autres, ainsi les malus de visée des ennemis sont réduits de moitié. Chaque attaque physique prodiguée par la créature force un jet de stabilité pour ne pas être repoussé de 1d4 cases en arrière et tomber au sol.', 'monstres', 'Bestiaire 2.0 › ligne 23296');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/ottar-chariot#carte:ottar-chariot', 3, NULL, NULL, 'Rempart solide', 'L’AP et l’AM de cette créature sont très élevés, pour affaiblir son armure, il faut réussir à le toucher avec un coup qui fait des dégâts supérieurs à sa valeur d’armure. Chaque coup réussi divisera par 2 ses AP et AM sur le morceau ciblé.', 'monstres', 'Bestiaire 2.0 › ligne 23296');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/ottar-chariot#carte:ottar-chariot', 4, NULL, NULL, 'Force démesurée', 'Cette créature peut dépasser la limite de Force de 1.', 'monstres', 'Bestiaire 2.0 › ligne 23296');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/ottar-chariot#carte:ottar-chariot', 5, NULL, NULL, 'Obscurité avantageuse', 'Cette créature est avantagée dans le noir, il impose un malus de 5% à tout les jets hostiles envers lui et toutes ses attaques font 1d de dégâts supplémantaire.', 'monstres', 'Bestiaire 2.0 › ligne 23296');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/ottar-chariot#carte:ottar-chariot', 6, NULL, NULL, 'Charge sans peur', 'Permet d''avoir un bonus de +7 au jet d''initiative.', 'monstres', 'Bestiaire 2.0 › ligne 23296');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/ours-garou#carte:ours-garou', 1, NULL, NULL, 'Haine mutuelle', 'Cette créature inflige un bonus +10 dégâts contre les Orios mais ces derniers ont également le même bonus sur cette première.', 'monstres', 'Bestiaire 2.0 › ligne 23584');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/ours-garou#carte:ours-garou', 2, NULL, NULL, 'Force démesurée', 'Cette créature peut dépasser la limite de Force de 1.', 'monstres', 'Bestiaire 2.0 › ligne 23584');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/ours-garou#carte:ours-garou', 3, '[EP2]', 2, 'Aura de peur', 'Inflige un malus de -10% au jet de défense aux ennemis à deux cases.', 'monstres', 'Bestiaire 2.0 › ligne 23584');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/ours-garou#carte:ours-garou', 4, '[EP3]', 3, 'Sang contrôlé', 'Immunisé au saignement.', 'monstres', 'Bestiaire 2.0 › ligne 23584');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/ours-garou#carte:ours-garou', 5, '[EP4]', 4, 'Attaque sanglante', 'Les armes naturelles de cette créature obligent le jet de vigueur pour ne pas prendre “Saignement 1”.', 'monstres', 'Bestiaire 2.0 › ligne 23584');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/ours-garou#carte:ours-garou', 6, '[EP5]', 5, 'Patience', 'Cette créature peut consommer un tour pour obtenir +1 action à son prochain tour. (1 fois/combat)', 'monstres', 'Bestiaire 2.0 › ligne 23584');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/ours-garou#carte:ours-garou', 7, '[EP6]', 6, 'Gigantisme', 'Cette créature peut utiliser l’arc de guerre géant avec les bras seulement.', 'monstres', 'Bestiaire 2.0 › ligne 23584');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/ours-garou#carte:ours-garou', 8, '[EP7]', 7, 'Fureur animale', 'Chaque attaque avec l’arme de corps à corps sera systématiquement suivie d’une attaque de morsure qui infligera 2d10 de dégâts d’estoc.', 'monstres', 'Bestiaire 2.0 › ligne 23584');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/ours-garou#carte:ours-garou', 9, '[EP8]', 8, 'Rage d’ours', 'Cette créature peut consommer son tour à galvaniser ses alliés, leur donnant un boost de +5 aux dégâts pendant 3 tours. (1 fois/combat)', 'monstres', 'Bestiaire 2.0 › ligne 23584');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/ours-garou#carte:ours-garou', 10, '[EP9]', 9, 'Rage de sang', 'Cette créature peut consommer son tour à enrager ses alliés, leur donnant la capacité de faire +10 dégâts contre les cibles qui ont un état de saignement pendant 4 tours. (1 fois/combat)', 'monstres', 'Bestiaire 2.0 › ligne 23584');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/ours-garou#carte:ours-garou', 11, '[EP10]', 10, 'Super force', 'Cette créature ne peut pas avoir de croix à la Force.', 'monstres', 'Bestiaire 2.0 › ligne 23584');
