INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/presque-ottar#carte:presque-ottar', 1, NULL, NULL, 'Effondrement chakratique', 'Son chakra s’effondre et sa magie est hors de contrôle, cette créature obtient quatres dons selon si elle est mono magie ou bi-magie. Voir tableau plus bas.', 'monstres', 'Bestiaire 2.0 › ligne 22828');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/radrak-frenetique#carte:radrak-frenetique-adulte', 1, NULL, NULL, 'Folle de guerre', 'Cette créature doit avancer vers l’ennemi, elle ne peut pas attendre et est immunisée contre toutes formes de peur.', 'monstres', 'Bestiaire 2.0 › ligne 24593');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/radrak-frenetique#carte:radrak-frenetique-adulte', 2, NULL, NULL, 'Grande créature', 'Cette créature est bien plus grande que les autres, ainsi les malus de visée des ennemis sont réduits de moitié. Chaque attaque physique prodiguée par la créature force un jet de stabilité pour ne pas être repoussé de 1d4 cases en arrière et tomber au sol.', 'monstres', 'Bestiaire 2.0 › ligne 24593');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/radrak-frenetique#carte:radrak-frenetique-adulte', 3, NULL, NULL, 'Anti-magie', 'Cette créature est totalement immunisée à la magie.', 'monstres', 'Bestiaire 2.0 › ligne 24593');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/radrak-frenetique#carte:radrak-frenetique-adulte', 4, NULL, NULL, 'Aveugle naturel', 'Cette créature est naturellement aveugle, ce qui l''immunise de tous les effets, attaques ou altérations d’état lié à la vue. Cet aveuglement ne l’empêche pas de connaître son environnement et de savoir où sont ses ennemis, la Perception n’est donc pas endommagée.', 'monstres', 'Bestiaire 2.0 › ligne 24593');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/radrak-frenetique#carte:radrak-frenetique-adulte', 5, NULL, NULL, 'Son strident', 'Cette créature est capable de faire résonner un son strident sur tout le terrain qui va empêcher l’utilisation de la magie pendant 2 tours complets. (4 tours de recharge)', 'monstres', 'Bestiaire 2.0 › ligne 24593');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/radrak-frenetique#carte:radrak-frenetique-adulte', 6, NULL, NULL, 'Vulnérabilité acide', 'Cette créature possède une vulnérabilité contre les dégâts d’acide, les sorts affligeants des dégâts d’acide ne sont pas annulés mais leur effets secondaires oui.', 'monstres', 'Bestiaire 2.0 › ligne 24593');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/radrak-frenetique#carte:radrak-frenetique-adulte', 7, NULL, NULL, 'Destruction', 'Le coup critique de cette créature retire automatiquement un cran de solidité à l’arme ou morceau d’armure.', 'monstres', 'Bestiaire 2.0 › ligne 24593');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/radrak-frenetique#carte:radrak-frenetique-jeune', 1, NULL, NULL, 'Folle de guerre', 'Cette créature doit avancer vers l’ennemi, elle ne peut pas attendre et est immunisée contre toutes formes de peur.', 'monstres', 'Bestiaire 2.0 › ligne 24536');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/radrak-frenetique#carte:radrak-frenetique-jeune', 2, NULL, NULL, 'Anti-magie', 'Cette créature est totalement immunisée à la magie.', 'monstres', 'Bestiaire 2.0 › ligne 24536');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/radrak-frenetique#carte:radrak-frenetique-jeune', 3, NULL, NULL, 'Aveugle naturel', 'Cette créature est naturellement aveugle, ce qui l''immunise de tous les effets, attaques ou altérations d’état lié à la vue. Cet aveuglement ne l’empêche pas de connaître son environnement et de savoir où sont ses ennemis, la Perception n’est donc pas endommagée.', 'monstres', 'Bestiaire 2.0 › ligne 24536');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/radrak-frenetique#carte:radrak-frenetique-jeune', 4, NULL, NULL, 'Son strident', 'Cette créature est capable de faire résonner un son strident sur tout le terrain qui va empêcher l’utilisation de la magie pendant 2 tours complets. (4 tours de recharge)', 'monstres', 'Bestiaire 2.0 › ligne 24536');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/radrak-frenetique#carte:radrak-frenetique-jeune', 5, NULL, NULL, 'Vulnérabilité acide', 'Cette créature possède une vulnérabilité contre les dégâts d’acide, les sorts affligeants des dégâts d’acide ne sont pas annulés mais leur effets secondaires oui.', 'monstres', 'Bestiaire 2.0 › ligne 24536');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/radrak-frenetique#carte:radrak-frenetique-sanguin', 1, NULL, NULL, 'Folle de guerre', 'Cette créature doit avancer vers l’ennemi, elle ne peut pas attendre et est immunisée contre toutes formes de peur.', 'monstres', 'Bestiaire 2.0 › ligne 24655');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/radrak-frenetique#carte:radrak-frenetique-sanguin', 2, NULL, NULL, 'Grande créature', 'Cette créature est bien plus grande que les autres, ainsi les malus de visée des ennemis sont réduits de moitié. Chaque attaque physique prodiguée par la créature force un jet de stabilité pour ne pas être repoussé de 1d4 cases en arrière et tomber au sol.', 'monstres', 'Bestiaire 2.0 › ligne 24655');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/radrak-frenetique#carte:radrak-frenetique-sanguin', 3, NULL, NULL, 'Anti-magie', 'Cette créature est totalement immunisée à la magie.', 'monstres', 'Bestiaire 2.0 › ligne 24655');
