INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/radrak-frenetique#carte:radrak-frenetique-sanguin', 7, NULL, NULL, 'Destruction', 'Le coup critique de cette créature retire automatiquement un cran de solidité à l’arme ou morceau d’armure.', 'monstres', 'Bestiaire 2.0 › ligne 24655');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/radrak-frenetique#carte:radrak-frenetique-sanguin', 8, NULL, NULL, 'Inarrêtable', 'Cette créature ne peut être arrêtée dans son élan, seule une autre chose inarrêtable peut être utilisée pour l’arrêter.', 'monstres', 'Bestiaire 2.0 › ligne 24655');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/rat#carte:rat-gris', 1, NULL, NULL, 'Demi-santé', 'Cette créature a deux fois moins de santé.', 'monstres', 'Bestiaire 2.0 › ligne 24793');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/rat#carte:rat-gris', 2, NULL, NULL, 'Petit sournois', 'Quand l’adversaire n’est pas attentif à l’attaquant, permet d’infliger un bonus de 1d4 dégâts en plus des dégâts de l’arme.', 'monstres', 'Bestiaire 2.0 › ligne 24793');
