INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/sanglier#carte:gros-sanglier', 1, NULL, NULL, 'Charge', 'Cette créature est capable d’infliger 1d de dégâts supplémentaire si elle parcourt plus de 4 cases avant son attaque.', 'monstres', 'Bestiaire 2.0 › ligne 25228');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/sanglier#carte:gros-sanglier', 2, NULL, NULL, 'Fermeté', 'Cette créature ne subit aucun dégâts de recul en plus d’infliger un bonus de dégâts de +5 avec toute attaque de charge.', 'monstres', 'Bestiaire 2.0 › ligne 25228');
