INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/sanglier#carte:sanglier-de-terre', 4, NULL, NULL, 'Super Santé', 'Cette créature a le double de PV.', 'monstres', 'Bestiaire 2.0 › ligne 25276');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/saurotudo#carte:saurotudo-jeune', 1, NULL, NULL, 'Grande créature', 'Cette créature est bien plus grande que les autres, ainsi les malus de visée des ennemis sont réduits de moitié. Chaque attaque physique prodiguée par la créature force un jet de stabilité pour ne pas être repoussé de 1d4 cases en arrière et tomber au sol.', 'monstres', 'Bestiaire 2.0 › ligne 25341');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/saurotudo#carte:saurotudo-jeune', 2, NULL, NULL, 'Balayage', 'Cette créature possède une arme (queue) qui est capable de toucher toute les cibles autour d’elle en échange de 30% de réussite.', 'monstres', 'Bestiaire 2.0 › ligne 25341');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/saurotudo#carte:saurotudo-jeune', 3, NULL, NULL, 'Camouflage', 'Dans le bon environnement (marais, eau), cette créature peut complètement disparaître et obliger ses adversaires à le chercher. Peut profiter d’une attaque discrète.', 'monstres', 'Bestiaire 2.0 › ligne 25341');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/saurotudo#carte:saurotudo-jeune', 4, NULL, NULL, 'Écrasement', 'Le poids de cette créature est assez grand pour faire des dégâts colossaux contre les créatures deux fois moins grandes que lui. Par une action, cette créature peut faire un gros plaquage sur une ou plusieurs créatures plus petites qu’elle, les créatures doivent faire un test de réussite (95 ou moins) pour ne pas tomber dans le coma immédiatement.', 'monstres', 'Bestiaire 2.0 › ligne 25341');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/soldat-de-fer#carte:general-de-fer', 1, NULL, NULL, 'Inerte', 'Cette créature possède 10 de volonté et est donc immunisée contre les jets de Volonté (sauf les altérations d’état dont il est vulnérable, là il n’a que 50% de chance de les éviter).', 'monstres', 'Bestiaire 2.0 › ligne 25527');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/soldat-de-fer#carte:general-de-fer', 2, NULL, NULL, 'Multi-fer++', 'Cette créature est capable d’activer en IC n’importe quel sort de type “fer” et d’avoir un bonus de +6 aux dégâts. Dure 3 tours.', 'monstres', 'Bestiaire 2.0 › ligne 25527');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/soldat-de-fer#carte:general-de-fer', 3, NULL, NULL, 'Laser de fer++', 'Tire tous les tours un laser qui passe à travers toutes les protections physiques, magiques, la barrière. Il est parable et esquivable. Ceci est un IC.', 'monstres', 'Bestiaire 2.0 › ligne 25527');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/soldat-de-fer#carte:lieutenant-de-fer', 1, NULL, NULL, 'Inerte', 'Cette créature possède 10 de volonté et est donc immunisée contre les jets de Volonté (sauf les altérations d’état dont il est vulnérable, là il n’a que 50% de chance de les éviter).', 'monstres', 'Bestiaire 2.0 › ligne 25470');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/soldat-de-fer#carte:lieutenant-de-fer', 2, NULL, NULL, 'Multi-fer+', 'Cette créature est capable d’activer en IC n’importe quel sort de type “fer” et avoir un bonus de +3 aux dégâts. Dure 3 tours.', 'monstres', 'Bestiaire 2.0 › ligne 25470');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/soldat-de-fer#carte:lieutenant-de-fer', 3, NULL, NULL, 'Laser de fer+', 'Tire tous les deux tours un laser qui passe à travers toutes les protections physiques, magiques, la barrière. Il est parable et esquivable. Ceci est un IC.', 'monstres', 'Bestiaire 2.0 › ligne 25470');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/soldat-de-fer#carte:soldat-de-fer', 1, NULL, NULL, 'Inerte', 'Cette créature possède 10 de volonté et est donc immunisée contre les jets de Volonté (sauf les altérations d’état dont il est vulnérable, là il n’a que 50% de chance de les éviter).', 'monstres', 'Bestiaire 2.0 › ligne 25413');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/soldat-de-fer#carte:soldat-de-fer', 2, NULL, NULL, 'Multi-fer', 'Cette créature est capable d’activer en IC n’importe quel sort de type “fer” mais sans avoir le bonus de dégâts. Dure 3 tours.', 'monstres', 'Bestiaire 2.0 › ligne 25413');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/soldat-de-fer#carte:soldat-de-fer', 3, NULL, NULL, 'Laser de fer', 'Tire tous les trois tours un laser qui passe à travers toutes les protections physiques, magiques, la barrière. Il est parable et esquivable. Ceci est un IC.', 'monstres', 'Bestiaire 2.0 › ligne 25413');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/solecorche#carte:solecorche', 1, NULL, NULL, 'Non-Mort', 'Une créature non-mort est dépourvue de morale et d''émotion ce qu''il l''a rendue immunisée aux sorts mentaux ainsi qu''une immunité contre le poison et la maladie. Elle bénéficie également d''un bonus de +60 pour l''intimidation. Sa volonté est à 9 (les jets de vigueur/fermeté contre des effets de magie dont il est vulnérable divise par 2 les chances de les réussir).', 'monstres', 'Bestiaire 2.0 › ligne 25588');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/solecorche#carte:solecorche', 2, NULL, NULL, 'Téméraire', 'Cette créature est toujours en offensive et ne possède pas le malus pour toucher sa cible.', 'monstres', 'Bestiaire 2.0 › ligne 25588');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/solecorche#carte:solecorche', 3, NULL, NULL, 'Force Solaire', 'Perd 20% de sa santé à la fin de chacun de ses tours mais a un bonus de 10 à toutes ses attaques (15 si il y a la météo "grand soleil").', 'monstres', 'Bestiaire 2.0 › ligne 25588');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/solecorche#carte:solecorche', 4, NULL, NULL, 'Photophile', 'Cette créature attire les sorts d''attaques de lumière vers lui et ne prend pas de dégâts des sorts de soin de la lumière.', 'monstres', 'Bestiaire 2.0 › ligne 25588');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/solecorche#carte:solecorche-astral', 1, NULL, NULL, 'Non-Mort', 'Une créature non-mort est dépourvue de morale et d''émotion ce qu''il l''a rendue immunisée aux sorts mentaux ainsi qu''une immunité contre le poison et la maladie. Elle bénéficie également d''un bonus de +60 pour l''intimidation. Sa volonté est à 9 (les jets de vigueur/fermeté contre des effets de magie dont il est vulnérable divise par 2 les chances de les réussir).', 'monstres', 'Bestiaire 2.0 › ligne 25701');
