INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/solecorche#carte:solecorche-astral', 5, NULL, NULL, 'Explosion lumineuse', 'Lors de sa mort, il va exploser dans une explosion faite de lumière qui force le jet de vigueur à tous ceux qui sont à 5 cases ou moins de lui, si les cibles ratent, elles prennent "Aveuglement 2".', 'monstres', 'Bestiaire 2.0 › ligne 25701');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/solecorche#carte:solecorche-astral', 6, NULL, NULL, 'Lumière de super force', 'Annule 5 dégâts d’une attaque encaissé, cette réduction se recharge après chaque attaque et elle n’est pas affectée par les attaques qui ignorent les défenses.', 'monstres', 'Bestiaire 2.0 › ligne 25701');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/solecorche#carte:solecorche-brillant', 1, NULL, NULL, 'Non-Mort', 'Une créature non-mort est dépourvue de morale et d''émotion ce qu''il l''a rendue immunisée aux sorts mentaux ainsi qu''une immunité contre le poison et la maladie. Elle bénéficie également d''un bonus de +60 pour l''intimidation. Sa volonté est à 9 (les jets de vigueur/fermeté contre des effets de magie dont il est vulnérable divise par 2 les chances de les réussir).', 'monstres', 'Bestiaire 2.0 › ligne 25643');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/solecorche#carte:solecorche-brillant', 2, NULL, NULL, 'Téméraire', 'Cette créature est toujours en offensive et ne possède pas le malus pour toucher sa cible.', 'monstres', 'Bestiaire 2.0 › ligne 25643');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/solecorche#carte:solecorche-brillant', 3, NULL, NULL, 'Force Solaire+', 'Perd 10% de sa santé à la fin de chacun de ses tours mais a un bonus de 10 à toutes ses attaques (15 si il y a la météo "grand soleil").', 'monstres', 'Bestiaire 2.0 › ligne 25643');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/solecorche#carte:solecorche-brillant', 4, NULL, NULL, 'Photophile', 'Cette créature attire les sorts d''attaques de lumière vers lui et ne prend pas de dégâts des sorts de soin de la lumière.', 'monstres', 'Bestiaire 2.0 › ligne 25643');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/solecorche#carte:solecorche-brillant', 5, NULL, NULL, 'Explosion lumineuse', 'Lors de sa mort, il va exploser dans une explosion faite de lumière qui force le jet de vigueur à tous ceux qui sont à 5 cases ou moins de lui, si les cibles ratent, elles prennent "Aveuglement 2".', 'monstres', 'Bestiaire 2.0 › ligne 25643');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/squelette#carte:squelette', 1, NULL, NULL, 'Non-Mort', 'Une créature non-mort est immunisée à la peur, à la couardise, à la fatigue, au poison, à la maladie. Les soins de lumière lui infligent des dégâts mais il a la possibilité de faire un jet de défense pour ne pas prendre les dégâts.', 'monstres', 'Bestiaire 2.0 › ligne 25778');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/squelette#carte:squelette', 2, NULL, NULL, 'Squelettique', 'Rend cette créature immunisée aux attaques d’estoc.', 'monstres', 'Bestiaire 2.0 › ligne 25778');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/squelette#carte:squelette', 3, NULL, NULL, 'Charge sans peur', 'Permet d''avoir un bonus de +7 au jet d''initiative.', 'monstres', 'Bestiaire 2.0 › ligne 25778');
