INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/squelette-mauvais#carte:squelette-mauvais-puissant', 3, NULL, NULL, 'Charge sans peur', 'Permet d''avoir un bonus de +7 au jet d''initiative.', 'monstres', 'Bestiaire 2.0 › ligne 26446');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/squelette-mauvais#carte:squelette-mauvais-puissant', 4, NULL, NULL, 'Résistance à la magie', 'Cette créature encaisse seulement la moitié des dégâts magiques.', 'monstres', 'Bestiaire 2.0 › ligne 26446');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/squelette-mauvais#carte:squelette-mauvais-puissant', 5, NULL, NULL, 'Tome de l’Ombre lvl5', 'Permet à cette créature de lancer des sorts de la magie de l’Ombre au niveau 5 de puissance.', 'monstres', 'Bestiaire 2.0 › ligne 26446');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/squelette-mauvais#carte:squelette-mauvais-puissant', 6, NULL, NULL, 'Tome de la Foudre lvl5', 'Permet à cette créature de lancer des sorts de la magie de la Foudre au niveau 5 de puissance.', 'monstres', 'Bestiaire 2.0 › ligne 26446');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/squelette-mauvais#carte:squelette-mauvais-puissant', 7, NULL, NULL, 'Général non-mort', 'Si d’autres non-mort sont présents sur le terrain et sont ses alliés : +6 dégâts et +1 Vitesse tant que la créature est en vie.', 'monstres', 'Bestiaire 2.0 › ligne 26446');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/squelette-venin#carte:squelette-poison', 1, NULL, NULL, 'Non-Mort', 'Une créature non-mort est immunisée à la peur, à la couardise, à la fatigue, au poison, à la maladie. Les soins de lumière lui infligent des dégâts mais il a la possibilité de faire un jet de défense pour ne pas prendre les dégâts.', 'monstres', 'Bestiaire 2.0 › ligne 26651');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/squelette-venin#carte:squelette-poison', 2, NULL, NULL, 'Squelettique', 'Rend cette créature immunisé aux attaques d’estoc', 'monstres', 'Bestiaire 2.0 › ligne 26651');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/squelette-venin#carte:squelette-poison', 3, NULL, NULL, 'Charge sans peur', 'Permet d''avoir un bonus de +7 au jet d''initiative.', 'monstres', 'Bestiaire 2.0 › ligne 26651');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/squelette-venin#carte:squelette-poison', 4, NULL, NULL, 'Attaque poison', 'L’arme de la créature est capable d’empoisonnement. Chaque attaque va obliger un jet de vigueur à la victime, si elle rate, elle prend “Poison 1”.', 'monstres', 'Bestiaire 2.0 › ligne 26651');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/squelette-venin#carte:squelette-poison', 5, NULL, NULL, 'Lanceur de sorts', 'Cette créature peut lancer les sorts, avec les niveaux de maîtrises maximum : Pieu d’os, Armure d’os.', 'monstres', 'Bestiaire 2.0 › ligne 26651');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/squelette-venin#carte:squelette-poison', 6, NULL, NULL, 'Double attaque', 'Cette créature possède deux armes et peut les utiliser en ambidextrie (avec les malus réduit à 10% et 20% pour les attaques)', 'monstres', 'Bestiaire 2.0 › ligne 26651');
