INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/squelette-venin#carte:squelette-toxique', 7, NULL, NULL, 'Pandémie', 'Quand un ennemi passe à côté de ses alliés alors qu’il souffre d’un poison, son allié est forcé de faire un jet de vigueur pour ne pas prendre le poison.', 'monstres', 'Bestiaire 2.0 › ligne 26713');
