INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/velue#carte:velue', 1, NULL, NULL, 'Haine mutuelle', 'Cette créature inflige un bonus +10 dégâts contre les Drakos mais ces derniers ont également le même bonus sur cette première.', 'monstres', 'Bestiaire 2.0 › ligne 26831');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/velue#carte:velue', 2, NULL, NULL, 'Magie aléatoire', 'Cette créature commence avec une magie aléatoire, le mj le détermine au dé (ou bien de lui-même). Elle peut lancer des sorts selon son niveau.', 'monstres', 'Bestiaire 2.0 › ligne 26831');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/velue#carte:velue', 3, NULL, NULL, 'Pics évolutifs', 'Cette créature est couverte de pics sur son corps qui ne font que grandir au fur et à mesure du temps. Chaque début de tour, la créature cumule +1AP/AM tant que ses pics sont présents (maximum 5 tours). Au bout de 3 tours elle peut les relâcher dans une attaque en cône de 6 de portée, elles infligent 5 dégâts d’estoc multiplié par le nombre de tour cumulé.', 'monstres', 'Bestiaire 2.0 › ligne 26831');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/velue#carte:velue', 4, '[EP2]', 2, 'Souffle élémentaire', 'Cette créature est capable de cracher un souffle lié à son élément. Ce souffle est capable d''infliger l''altération d''état lié à l''élément à hauteur de 35% de chance de l''infliger. (les joueurs doivent faire les jets en conséquence pour ne pas prendre l''altération d''état).', 'monstres', 'Bestiaire 2.0 › ligne 26831');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/velue#carte:velue', 5, '[EP3]', 3, 'Humidification', 'Dispose d''une protection qui vont ignorer les 10 premiers dégâts qui vont lui être infligés lors d''un combat (se recharge tous les 3 tours)', 'monstres', 'Bestiaire 2.0 › ligne 26831');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/velue#carte:velue', 6, '[EP4]', 4, 'Pics solide', 'Les pics donnent +2AP/AM au lieu de 1.', 'monstres', 'Bestiaire 2.0 › ligne 26831');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/velue#carte:velue', 7, '[EP5]', 5, 'Pics élémentaires', 'Les pics peuvent infliger des dégâts élémentaires liés à la magie de la créature.', 'monstres', 'Bestiaire 2.0 › ligne 26831');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/velue#carte:velue', 8, '[EP6]', 6, 'Super pics', 'Les dégâts de pics évolutifs passent à 10.', 'monstres', 'Bestiaire 2.0 › ligne 26831');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/velue#carte:velue', 9, '[EP7]', 7, 'Super souffle', 'Le souffle passe à 8 po maximum.', 'monstres', 'Bestiaire 2.0 › ligne 26831');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/velue#carte:velue', 10, '[EP8]', 8, 'Charge piquante', 'Au lieu d''envoyer les pics dans une direction en cône, la créature peut les utiliser pour faire une charge en avant qui inflige 20 dégâts de frappe par tour cumulé. Elle s’arrête au premier gros obstacle. Elle ne prend pas de dégâts de recul mais les pics disparaissent et la créature perd 1 tour et sa posture.', 'monstres', 'Bestiaire 2.0 › ligne 26831');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/velue#carte:velue', 11, '[EP9]', 9, 'Pics résistants', 'Les pics donnent +4AP/AM au lieu de 1.', 'monstres', 'Bestiaire 2.0 › ligne 26831');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/velue#carte:velue', 12, '[EP10]', 10, 'Hyper pics', 'Les dégâts de pics évolutifs passent à 20.', 'monstres', 'Bestiaire 2.0 › ligne 26831');
