INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/velue#carte:velue-superieur', 11, '[EP8]', 8, 'Charge piquante', 'Au lieu d''envoyer les pics dans une direction en cône, la créature peut les utiliser pour faire une charge en avant qui inflige 20 dégâts de frappe par tour cumulé. Elle s’arrête au premier gros obstacle. Elle ne prend pas de dégâts de recul mais les pics disparaissent et la créature perd 1 tour et sa posture.', 'monstres', 'Bestiaire 2.0 › ligne 26949');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/velue#carte:velue-superieur', 12, '[EP9]', 9, 'Pics résistants', 'Les pics donnent +4AP/AM au lieu de 1.', 'monstres', 'Bestiaire 2.0 › ligne 26949');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/velue#carte:velue-superieur', 13, '[EP10]', 10, 'Hyper pics', 'Les dégâts de pics évolutifs passent à 20.', 'monstres', 'Bestiaire 2.0 › ligne 26949');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/voromorphe#carte:voromorphe-adulte', 1, NULL, NULL, 'Adaptation élémentaire', 'Cette créature ne possède pas la même forme selon l’environnement où on la rencontre, chaque environnement peut être associé à une magie, et lui donne différents bonus :
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/voromorphe#carte:voromorphe-adulte', 2, NULL, NULL, 'Souffle élémentaire', 'Cette créature est capable de cracher un souffle lié à son élément. Ce souffle est capable d''infliger l''altération d''état lié à l''élément à hauteur de 35% de chance de l''infliger. (les joueurs doivent faire les jets en conséquence pour ne pas prendre l''altération d''état).', 'monstres', 'Bestiaire 2.0 › ligne 27589');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/voromorphe#carte:voromorphe-adulte', 3, NULL, NULL, 'Grande créature', 'Cette créature est bien plus grande que les autres, ainsi les malus de visée des ennemis sont réduits de moitié. Chaque attaque physique prodiguée par la créature force un jet de stabilité pour ne pas être repoussé de 1d4 cases en arrière et tomber au sol.', 'monstres', 'Bestiaire 2.0 › ligne 27589');
