INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/zompi#carte:zompiceps', 2, NULL, NULL, 'Grande créature', 'Cette créature est bien plus grande que les autres, ainsi les malus de visée des ennemis sont réduits de moitié. Chaque attaque physique prodiguée par la créature force un jet de stabilité pour ne pas être repoussé de 1d4 cases en arrière et tomber au sol.', 'monstres', 'Bestiaire 2.0 › ligne 28385');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/zompi#carte:zompiceps', 3, NULL, NULL, 'Régénération partiel+', 'Cette créature récupère 10 santé au début de son tour.', 'monstres', 'Bestiaire 2.0 › ligne 28385');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/zompi#carte:zompiceps', 4, NULL, NULL, 'Crache spore', 'Crache des spores qui obligent toutes les créatures à 2 cases de lui de réussir un jet de vigueur, si elles ratent, elles sont étourdies pendant 1 tour.', 'monstres', 'Bestiaire 2.0 › ligne 28385');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/zompi#carte:zompiceps', 5, NULL, NULL, 'Dégustation d’eau', 'Absorbe les dégâts de l’élément eau, ce qui lui donne +5 dégâts à la prochaine attaque en plus de le soigner à hauteur de 5d6.', 'monstres', 'Bestiaire 2.0 › ligne 28385');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/zompi#carte:zompiceps', 6, NULL, NULL, 'Tête fongique', 'La tête est protégée et n’est plus considérée comme un point faible.', 'monstres', 'Bestiaire 2.0 › ligne 28385');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/zompi#carte:zompiceps', 7, NULL, NULL, 'Super armure', 'Cette créature possède une protection qui va demander un certain nombre de dégâts pour être détruite (25 dégâts), elle doit être détruite en un seul coup sinon elle se reconstruit immédiatement. Si jamais elle est détruite, elle revient au bout de 2 tours. Cette armure empêche tout dégâts à la santé de la créature, peu importe les moyens utilisés.', 'monstres', 'Bestiaire 2.0 › ligne 28385');
